import { GameEngine, Agent } from "../game";
import { GameEvent, Team } from "../../types";
import { HexUtils } from "../utils";
import { UNIT_VISUAL_HEIGHT, HUD_PADDING, UNIT_BODY_OFFSET } from "../../constants";

// Systems
import { VFXSystem } from "./vfx";
import { HUDSystem } from "./hud";
import { GridSystem } from "./grid";
import { CameraSystem } from "./CameraSystem";
import * as VFXSpawners from "./vfx/spawners";

const HUD_TEXT_OFFSET = UNIT_VISUAL_HEIGHT + HUD_PADDING + 20;
const KILL_STREAK_WINDOW = 12.0; 

export class VisualEventListener {
    private killStreaks = new Map<string, { count: number, lastTime: number }>();
    private firstBlood = false;

    public process(
        events: GameEvent[], 
        engine: GameEngine, 
        vfx: VFXSystem, 
        hud: HUDSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        if (engine.battleTime < 0.1) {
            this.killStreaks.clear();
            this.firstBlood = false;
        }

        events.forEach(event => {
            const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
            const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
            const visualGroundY = event.pos.y - terrainHeight;

            // 1. HUD & Text
            if (['DAMAGE', 'HEAL', 'CC_APPLIED'].includes(event.type)) {
                 const baseY = visualGroundY - HUD_TEXT_OFFSET; 
                 let text = "";
                 let color = "#fff";
                 let size = 16;
                 let type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE';
                 let xOffset = 0;

                 if (event.type === 'DAMAGE') {
                     const val = Math.abs(event.value || 0);
                     text = val.toString();
                     const isCrit = val > 100;
                     color = isCrit ? '#ef4444' : '#fff'; 
                     size = isCrit ? 24 : 16;
                     type = 'DAMAGE';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else if (event.type === 'HEAL') {
                     text = "+" + Math.abs(event.value || 0);
                     color = '#4ade80';
                     type = 'HEAL';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else {
                     text = event.text || "";
                     color = event.color || "#fff";
                     type = 'CC';
                     size = 14;
                     xOffset = -45;
                 }

                 if (text) hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);

            } else if (event.type === 'CAST_START') {
                 if (event.skill && event.skill.tag !== 'BASIC') {
                     const isUlt = event.skill.tag === 'ULT';
                     const baseY = visualGroundY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
                     const xOffset = 55; 
                     hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
                 }
            } else if (event.type === 'CAST_FINISH') {
                 if (event.skill && event.skill.tag === 'ULT') {
                     // Only spawn instant impact logic here if it's not a projectile
                     // If it is projectile, the HIT event handles the big boom
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.2); 
                     }
                 }
            } else if (event.type === 'KILL' && event.sourceId) {
                // ... (Kill Streak Logic kept same for brevity, it works fine) ...
                const now = engine.battleTime;
                const killer = event.sourceId;
                const killerAgent = engine.agents.find(a => a.id === killer);

                if (!this.firstBlood) {
                    this.firstBlood = true;
                    if (killerAgent) {
                        const kHex = HexUtils.fromPx(killerAgent.px, killerAgent.py, engine.mapConfig);
                        const kH = grid.getTerrainHeight(kHex.q, kHex.r, engine);
                        hud.addFloatingText(killerAgent.px, killerAgent.py - kH - HUD_TEXT_OFFSET - 60, "FIRST BLOOD", "#ef4444", 36, 'KILL_STREAK');
                        camera.addTrauma(0.3);
                    }
                }

                let streak = 1;
                const existing = this.killStreaks.get(killer);
                if (existing && now - existing.lastTime <= KILL_STREAK_WINDOW) streak = existing.count + 1;

                this.killStreaks.set(killer, { count: streak, lastTime: now });

                if (streak >= 2 && killerAgent) {
                    let streakText = "DOUBLE KILL";
                    let streakColor = "#cbd5e1";
                    if (streak === 3) { streakText = "TRIPLE KILL"; streakColor = "#fcd34d"; }
                    else if (streak === 4) { streakText = "QUADRA KILL"; streakColor = "#fb923c"; }
                    else if (streak >= 5) { streakText = "PENTA KILL"; streakColor = "#ef4444"; }

                    const kHex = HexUtils.fromPx(killerAgent.px, killerAgent.py, engine.mapConfig);
                    const kH = grid.getTerrainHeight(kHex.q, kHex.r, engine);
                    hud.addFloatingText(killerAgent.px, killerAgent.py - kH - HUD_TEXT_OFFSET - 40, streakText, streakColor, 32 + (streak * 4), 'KILL_STREAK');
                    camera.addTrauma(0.2 + streak * 0.1);
                }
            }

            // 3. VFX Handling
            switch (event.type) {
                case 'VISUAL_SLASH':
                    if (event.sourceId && event.targetId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        const target = engine.agents.find(a => a.id === event.targetId);
                        if (source && target) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                            const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                            const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                            VFXSpawners.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
                        }
                    }
                    break;

                case 'DAMAGE': 
                    const dmg = Math.abs(event.value || 0);
                    // Standard hit spark
                    if (event.sourceId && event.targetId) {
                        const s = engine.agents.find(a => a.id === event.sourceId);
                        const t = engine.agents.find(a => a.id === event.targetId);
                        if (s && t) {
                            const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                            const dx = t.px - s.px; const dy = t.py - s.py;
                            const len = Math.sqrt(dx*dx + dy*dy);
                            if (len > 0) {
                                const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';
                                VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, event.color || '#fff', type);
                            }
                        }
                    } else {
                        VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
                    }
                    if (dmg > 50) camera.addTrauma(0.15);
                    break;

                case 'VISUAL_BEAM':
                    if (event.sourceId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        if (source) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                            VFXSpawners.spawnBeam(vfx, source.px, source.py - sH - 40, event.pos.x, visualGroundY - 30, event.color || '#fff');
                            VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
                        }
                    }
                    break;

                case 'PROJECTILE_HIT': 
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                    break;

                case 'DEATH':
                    const dAgent = engine.agents.find(a => a.id === event.sourceId);
                    if (dAgent) VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role);
                    camera.addTrauma(0.3); 
                    break;

                case 'SPAWN':
                    VFXSpawners.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                    break;

                case 'CAST_BREAK':
                    VFXSpawners.spawnDomainShatter(vfx, event.pos.x, event.pos.y, event.value || 1, event.color || '#fff');
                    camera.addTrauma(0.1);
                    break;
            }
        });
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;

        // Find Source Agent to determine Faction Style
        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.5);

            // --- 1. CENTER PIECE: FACTION SPECIFIC RITUAL ---
            if (faction === Team.BLUE) {
                // Imperial: Divine Pillar (Order)
                // Spawn a clean, geometric pillar of light
                VFXSpawners.spawnDivinePillar(vfx, event.pos.x, centerVisualY, color, 1.5, 0);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 1.2);
            } else {
                // Covenant: Hellgate (Chaos)
                // Spawn fissures, blood, and dark energy
                VFXSpawners.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            // --- 2. AOE RIPPLE: PER TILE SPLASH ---
            if (skill?.type === 'AOE') {
                const radius = skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;

                        const dist = HexUtils.dist(centerHex, h);
                        // Delay creates the "Ripple" expanding outward
                        const delay = dist * 0.08; 

                        // Spawn a sub-effect on this specific tile
                        VFXSpawners.spawnGridImpact(vfx, tilePos.x, tileVisualY, color, faction, delay);

                        // --- 3. PERSISTENT FIELD EFFECTS (SMOKE/FIRE) ---
                        // If skill has DoT/Slow, spawn lingering particles
                        if (skill.ccType === 'DOT' || skill.ccType === 'SLOW' || skill.ccType === 'SILENCE') {
                            VFXSpawners.spawnLingeringField(vfx, tilePos.x, tileVisualY, color, skill.ccType, 4.0, delay);
                        }
                    }
                });
            } else {
                // Single Target Ult Explosion
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.2, 0.8, 'SPARK');
            }
        } else {
            // Normal Skill Logic
            if (skill?.type === 'AOE') {
                const radius = skill.aoeRadius || 1;
                const affected = HexUtils.range(centerHex, radius);

                // Add Decal at center
                VFXSpawners.addDecal(vfx, event.pos.x, centerVisualY, color);

                affected.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;
                        const dist = HexUtils.dist(centerHex, h);

                        // Smaller ripple for normal skills
                        if (dist <= radius) {
                            if (Math.random() < 0.6) { // Not every tile needs a heavy hit for basics
                                VFXSpawners.addImpact(vfx, tilePos.x, tileVisualY, 0, color, 'RING', 0.4);
                            }
                            if (skill.ccType === 'DOT' || skill.ccType === 'SLOW') {
                                VFXSpawners.spawnLingeringField(vfx, tilePos.x, tileVisualY, color, skill.ccType, 3.0, dist * 0.05);
                            }
                        }
                    }
                });
            } else {
                // Single hit
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.6);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 1.0, 0.5, 'SPARK');
            }
        }
    }
}

import { VFXSystem } from "../vfx";
import { Team, Role } from "../../../types";
import { SpriteManager } from "../../sprites";

// =========================================================================================
// 🏭 PARTICLE SPAWNERS (Factory Functions)
// =========================================================================================

// --- 1. FACTION ULTIMATES ---

export function spawnDivinePillar(system: VFXSystem, x: number, y: number, color: string, life: number, delay: number = 0) {
    // Blue/Imperial: Clean, Vertical, Geometric
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 100; // Radius
    p.type = 'PILLAR'; // Uses "Order" render style
    p.delay = delay;
    system.state.particles.push(p);
}

export function spawnBloodRitual(system: VFXSystem, x: number, y: number, color: string, life: number) {
    // Red/Covenant: Chaotic, Ground-breaking, Dark
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 0;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 120; // Radius
    p.type = 'DOMAIN'; // Re-using Domain type but with chaos flag in renderer
    p.delay = 0;
    system.state.particles.push(p);

    // Add rising "Blood/Darkness" debris
    for(let i=0; i<8; i++) {
        const d = system.state.getParticle();
        d.x = x + (Math.random()-0.5)*50; 
        d.y = y + (Math.random()-0.5)*30; 
        d.z = 0;
        d.vx = (Math.random()-0.5)*50;
        d.vy = (Math.random()-0.5)*50;
        d.vz = 100 + Math.random() * 200; // Rising slow
        d.life = life * 0.8; d.maxLife = life * 0.8;
        d.color = '#000'; // Obsidian chunks
        d.size = 5 + Math.random() * 8;
        d.type = 'DEBRIS';
        d.rotation = Math.random();
        d.vRotation = Math.random();
        system.state.particles.push(d);
    }
}

// --- 2. GRID CONSISTENCY ---

export function spawnGridImpact(system: VFXSystem, x: number, y: number, color: string, team: Team, delay: number) {
    // A smaller effect for EACH tile in an AOE

    if (team === Team.BLUE) {
        // Blue: Mini pillar / Light shaft
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = 0;
        p.life = 0.6; p.maxLife = 0.6;
        p.color = color;
        p.size = 40; // Fits within a Hex
        p.type = 'PILLAR'; // Mini pillar
        p.delay = delay;
        system.state.particles.push(p);
    } else {
        // Red: Ground erupting spike
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = 0;
        p.life = 0.6; p.maxLife = 0.6;
        p.color = color;
        p.size = 40;
        p.type = 'SHOCKWAVE'; // Will render as a jagged blast
        p.delay = delay;
        system.state.particles.push(p);

        // Add a spark
        const s = system.state.getParticle();
        s.x = x; s.y = y; s.z = 10;
        s.vx = 0; s.vy = 0; s.vz = 150;
        s.life = 0.4; s.maxLife = 0.4;
        s.color = color; s.size = 20;
        s.type = 'SPARK';
        s.delay = delay;
        system.state.particles.push(s);
    }
}

export function spawnLingeringField(system: VFXSystem, x: number, y: number, color: string, type: string, duration: number, delay: number) {
    // Spawns smoke/clouds that persist
    const count = 3;
    for(let i=0; i<count; i++) {
        const p = system.state.getParticle();
        p.x = x + (Math.random()-0.5)*20;
        p.y = y + (Math.random()-0.5)*15;
        p.z = 5;

        // Drift slowly
        p.vx = (Math.random()-0.5) * 20;
        p.vy = (Math.random()-0.5) * 20;
        p.vz = 10 + Math.random() * 20; // Rise slowly

        p.life = duration + Math.random(); 
        p.maxLife = p.life;
        p.color = color;
        p.size = 20 + Math.random() * 20;
        p.type = 'SMOKE';
        p.delay = delay + Math.random() * 0.5;

        system.state.particles.push(p);
    }
}

// --- 3. EXISTING HELPERS (Preserved) ---

export function spawnDirectionalImpact(system: VFXSystem, x: number, y: number, z: number, dirX: number, dirY: number, color: string, type: 'PHYSICAL' | 'MAGICAL') {
    const isPhysical = type === 'PHYSICAL';
    const baseAngle = Math.atan2(dirY, dirX);
    const count = isPhysical ? 8 : 10;
    const spread = 0.8; 

    for (let i = 0; i < count; i++) {
        const angle = baseAngle + (Math.random() - 0.5) * spread;
        const speed = 250 + Math.random() * 250; 
        const p = system.state.getParticle();

        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * speed;
        p.vy = Math.sin(angle) * speed;
        p.vz = 50 + Math.random() * 200; 

        p.life = 0.6 + Math.random() * 0.4; 
        p.maxLife = p.life;
        p.color = isPhysical ? '#e2e8f0' : color; 
        p.size = 3 + Math.random() * 3; 
        p.type = 'CHIP'; 
        p.rotation = Math.random() * Math.PI;
        p.vRotation = (Math.random()-0.5) * 20;
        p.delay = 0;

        system.state.particles.push(p);
    }
    spawnExplosion(system, x, y, z, 3, '#fff', 0.2, 0.4, 'SMOKE');
}

export function spawnConnectorSlash(system: VFXSystem, x1: number, y1: number, x2: number, y2: number, color: string, visual: string) {
    const p = system.state.getParticle();
    p.x = x1; p.y = y1 - 30; 
    p.targetX = x2; p.targetY = y2 - 30;
    p.z = 30;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = 0.25; p.maxLife = 0.25;
    p.color = color; p.size = 10;
    p.type = 'BEAM'; 
    p.delay = 0;
    system.state.particles.push(p);
}

export function spawnUnitShatter(system: VFXSystem, x: number, y: number, team: Team, role: Role) {
    const assets = SpriteManager.getUnitImages(role, team);
    const spawnSprite = (img: HTMLCanvasElement, scale: number, zBase: number, vZ: number) => {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = zBase; 
        const angle = Math.random() * Math.PI * 2;
        const dist = 100 + Math.random() * 150; 
        p.vx = Math.cos(angle) * dist; p.vy = Math.sin(angle) * dist; p.vz = vZ;
        p.life = 3.0; p.maxLife = 3.0;
        p.color = '#fff'; p.size = 64 * scale; 
        p.type = 'SPRITE'; p.image = img;
        p.rotation = Math.random() * Math.PI * 2; p.vRotation = (Math.random() - 0.5) * 20; 
        system.state.particles.push(p);
    };

    const baseColor = '#52525b';
    for (let i = 0; i < 6; i++) {
        const p = system.state.getParticle();
        const angle = (i / 6) * Math.PI * 2 + (Math.random()-0.5)*0.5;
        p.x = x; p.y = y; p.z = 5;
        const speed = 100 + Math.random() * 100;
        p.vx = Math.cos(angle) * speed; p.vy = Math.sin(angle) * speed; p.vz = 50 + Math.random() * 100; 
        p.life = 3.0; p.maxLife = 3.0;
        p.color = baseColor; p.size = 10 + Math.random() * 10;
        p.type = 'SHARD'; p.rotation = angle; p.vRotation = (Math.random()-0.5)*10;
        system.state.particles.push(p);
    }

    spawnSprite(assets.weapon, 0.7, 50, 400); 
    spawnSprite(assets.icon, 0.6, 70, 300);   

    const coreColor = team === Team.BLUE ? '#3b82f6' : '#ef4444';
    for (let i = 0; i < 8; i++) {
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = 40;
        const angle = Math.random() * Math.PI * 2;
        const speed = 50 + Math.random() * 150;
        p.vx = Math.cos(angle) * speed; p.vy = Math.sin(angle) * speed; p.vz = 150 + Math.random() * 150;
        p.life = 2.0; p.maxLife = 2.0;
        p.color = coreColor; p.size = 6 + Math.random() * 6;
        p.type = 'DEBRIS'; 
        p.rotation = Math.random() * Math.PI; p.vRotation = (Math.random()-0.5) * 15;
        system.state.particles.push(p);
    }
    addDecal(system, x, y, '#000'); 
    spawnExplosion(system, x, y, 10, 8, '#71717a', 0.5, 1.0, 'SMOKE');
}

export function spawnDomainShatter(system: VFXSystem, x: number, y: number, radiusTiles: number, color: string) {
    const radiusPx = radiusTiles * 40; 
    const count = Math.max(12, radiusTiles * 8); 
    for (let i = 0; i < count; i++) {
        const angle = (i / count) * Math.PI * 2;
        const p = system.state.getParticle();
        const px = x + Math.cos(angle) * radiusPx;
        const py = y + Math.sin(angle) * radiusPx * 0.55; 
        p.x = px; p.y = py; p.z = 5; 
        const speed = 50 + Math.random() * 80;
        p.vx = Math.cos(angle) * speed; p.vy = Math.sin(angle) * speed; p.vz = 20 + Math.random() * 30;
        p.life = 0.5; p.maxLife = 0.5; 
        p.color = color; p.size = 2 + Math.random() * 2; 
        p.type = 'SPARK'; p.delay = 0;
        system.state.particles.push(p);
    }
    spawnExplosion(system, x, y, 10, 5, '#ffffff', 0.5, 0.5, 'SMOKE');
}

export function spawnBeam(system: VFXSystem, sx: number, sy: number, tx: number, ty: number, color: string) {
    const p = system.state.getParticle();
    p.x = sx; p.y = sy; p.z = 0; p.vx = 0; p.vy = 0; p.vz = 0;
    p.targetX = tx; p.targetY = ty;
    p.life = 0.4; p.maxLife = 0.4; p.color = color; p.size = 4; p.type = 'BEAM'; p.delay = 0;
    system.state.particles.push(p);
}

export function spawnDomainExpansion(system: VFXSystem, x: number, y: number, color: string, duration: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = duration; p.maxLife = duration;
    p.color = color; p.size = 0;
    p.type = 'DOMAIN'; p.delay = 0;
    system.state.particles.push(p);
}

export function spawnExplosion(system: VFXSystem, x: number, y: number, z: number, count: number, color: string, speed: number, life: number, type: 'SPARK' | 'SMOKE') {
    const safeCount = Math.min(type === 'SPARK' ? 12 : 6, count);
    for (let i = 0; i < safeCount; i++) {
        const angle = Math.random() * Math.PI * 2;
        const spd = Math.random() * 100 * speed;
        const p = system.state.getParticle();
        p.x = x; p.y = y; p.z = z;
        p.vx = Math.cos(angle) * spd; p.vy = Math.sin(angle) * spd;
        p.vz = (Math.random() * 100 + 50) * speed; 
        p.life = life * (0.6 + Math.random() * 0.4); p.maxLife = life;
        p.color = color;
        p.size = type === 'SPARK' ? Math.random() * 3 + 2 : Math.random() * 3 + 1;
        p.type = type; p.delay = 0;
        system.state.particles.push(p);
    }
}

export function spawnTeleport(system: VFXSystem, x: number, y: number, color: string) {
    spawnDivinePillar(system, x, y, color, 0.8, 0);
    addImpact(system, x, y, 5, color, 'RING', 0.8);
}

export function spawnShockwave(system: VFXSystem, x: number, y: number, color: string, life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = 10;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = 'SHOCKWAVE';
    p.delay = 0;
    system.state.particles.push(p);
}

export function addImpact(system: VFXSystem, x: number, y: number, z: number, color: string, type: 'RING', life: number) {
    const p = system.state.getParticle();
    p.x = x; p.y = y; p.z = z;
    p.vx = 0; p.vy = 0; p.vz = 0;
    p.life = life; p.maxLife = life;
    p.color = color; p.size = 0;
    p.type = type;
    p.delay = 0;
    system.state.particles.push(p);
}

export function addDecal(system: VFXSystem, x: number, y: number, color: string) {
    system.state.decals.push({
        x, y, color, life: 5.0, scale: 0.5 + Math.random() * 0.3
    });
}

import { Particle } from "../state";
import { isChaosStyle, normalizeHex } from "../utils";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Shared translation
        ctx.translate(p.x, p.y);

        if (p.type === 'SPRITE') {
            if (p.image) {
                const alpha = Math.min(1, (1 - progress) * 5); 
                ctx.globalAlpha = alpha;
                if (p.z < 20) {
                    ctx.save();
                    ctx.translate(0, p.z);
                    ctx.scale(1, 0.5);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.beginPath(); ctx.arc(0, 0, p.size/3, 0, Math.PI*2); ctx.fill();
                    ctx.restore();
                }
                ctx.rotate(p.rotation);
                const scale = p.size / 64; 
                ctx.scale(scale, scale);
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);
            }

        } else if (p.type === 'CHIP') {
            ctx.rotate(p.rotation); 
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - Math.pow(progress, 4);
            const s = p.size;
            ctx.beginPath();
            ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            ctx.fill();

        } else if (p.type === 'SHARD') {
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            const s = p.size;
            ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 1;
            ctx.stroke();

        } else if (p.type === 'SMOKE') {
            const r = p.size * (0.5 + progress * 2); 
            // Softer Alpha
            ctx.globalAlpha = (1 - progress) * 0.3;
            ctx.fillStyle = p.color; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'BLAST') {
            ctx.scale(1, 0.55); 
            const r = p.size * (progress * 2); 
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 5; 
            ctx.globalAlpha = (1 - progress) * 0.8;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                ctx.translate(-p.x, -p.y); 
                ctx.globalCompositeOperation = 'lighter';
                const sx = p.x; const sy = p.y;
                const tx = p.targetX; const ty = p.targetY;

                if (isChaos) {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.moveTo(sx, sy);
                    const segs = 10;
                    const dx = tx - sx; const dy = ty - sy;
                    for(let i=1; i<segs; i++) {
                        const ratio = i/segs;
                        const jit = (Math.random()-0.5) * 20;
                        ctx.lineTo(sx + dx * ratio + jit, sy + dy * ratio + jit);
                    }
                    ctx.lineTo(tx, ty);
                    ctx.stroke();
                    ctx.lineWidth = 1; ctx.strokeStyle = '#000'; ctx.stroke();
                } else {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 8;
                    ctx.lineCap = 'round';
                    ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(tx, ty); ctx.stroke();
                    ctx.lineWidth /= 2; ctx.strokeStyle = '#fff'; ctx.stroke();
                }
            }
        } else if (p.type === 'RING') {
            ctx.scale(1, 0.55); 
            const r = progress * 40;
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1 - progress;
            // Removed 'lighter' to reduce exposure, standard alpha blend
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'SPARK') {
            const r = p.size;
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - Math.pow(progress, 3); 
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'DEBRIS') {
            ctx.fillStyle = p.color;
            ctx.rotate(p.rotation);
            ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);

        } else if (p.type === 'PILLAR') {
            ctx.translate(0, -20); 
            this.drawDivinePillar(ctx, p, progress);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawBloodRitual(ctx, p, progress);
        }

        ctx.restore();
    },

    // 🏛️ BLUE: DIVINE PILLAR (ORDER)
    // Vertical light shaft, geometric rings, clean fade
    drawDivinePillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        // Fade in quickly, hold, fade out
        const lifeRatio = p.life / p.maxLife;
        let alpha = 0;
        if (lifeRatio > 0.8) alpha = (1 - lifeRatio) * 5; // Fade In
        else if (lifeRatio < 0.3) alpha = lifeRatio * 3.3; // Fade Out
        else alpha = 1.0; // Hold

        const height = 1200; 
        const width = p.size; // Should correspond to hex size approx

        ctx.save();
        ctx.scale(1, 0.55); 

        // 1. Ground Ring (Source-Over, Solid color)
        ctx.globalCompositeOperation = 'source-over';
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 3;
        ctx.globalAlpha = alpha * 0.5;
        ctx.beginPath(); ctx.arc(0, 0, width, 0, Math.PI*2); ctx.stroke();

        // 2. Rising Rings (Animation)
        ctx.globalCompositeOperation = 'lighter';
        ctx.lineWidth = 2;
        const ringCount = 3;
        for(let i=0; i<ringCount; i++) {
            const ringH = ((progress * 5 + i) % ringCount) * 100;
            const ringAlpha = (1 - ringH/300) * alpha;
            ctx.globalAlpha = ringAlpha * 0.5;
            // Fake 3D height by Y offset in iso
            ctx.beginPath(); ctx.ellipse(0, -ringH * 2, width, width, 0, 0, Math.PI*2); ctx.stroke();
        }

        ctx.restore();

        // 3. The Pillar Shaft (Gradient)
        // Use source-over for the core to avoid blinding white
        ctx.globalCompositeOperation = 'source-over';
        const coreGrad = ctx.createLinearGradient(0, 0, 0, -height);
        coreGrad.addColorStop(0, p.color); // Solid Color at base
        coreGrad.addColorStop(0.2, p.color);
        coreGrad.addColorStop(1, 'transparent'); // Fade up

        ctx.fillStyle = coreGrad;
        ctx.globalAlpha = alpha * 0.3; // Low alpha to see through
        ctx.fillRect(-width * 0.5, -height, width, height);

        // 4. Central Beam (Thinner, brighter)
        ctx.globalCompositeOperation = 'lighter';
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = alpha * 0.2;
        ctx.fillRect(-width * 0.1, -height, width * 0.2, height);
    },

    // 🩸 RED: BLOOD RITUAL (CHAOS)
    // Cracks, Dark Energy, Rising Bubbles
    drawBloodRitual(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
         const lifeRatio = p.life / p.maxLife;
         const alpha = Math.sin(lifeRatio * Math.PI); 
         const r = p.size;

         ctx.save();
         ctx.scale(1, 0.55); 

         // 1. The Void (Ground Hole)
         ctx.globalCompositeOperation = 'source-over'; 
         const voidGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
         voidGrad.addColorStop(0, '#000'); // Black center
         voidGrad.addColorStop(0.7, '#220000');
         voidGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = voidGrad;
         ctx.globalAlpha = alpha * 0.9;
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // 2. Cracks / Runes
         ctx.strokeStyle = p.color; // Red/Orange
         ctx.lineWidth = 3;
         ctx.globalAlpha = alpha;
         ctx.beginPath();
         // Jagged lines from center
         for(let i=0; i<6; i++) {
             const angle = i * (Math.PI/3) + progress;
             ctx.moveTo(0,0);
             ctx.lineTo(Math.cos(angle)*r, Math.sin(angle)*r);
         }
         ctx.stroke();

         // 3. Rising Dark Miasma (Noise)
         ctx.globalCompositeOperation = 'lighter'; // Glowy smoke
         ctx.fillStyle = p.color;
         const bubbles = 5;
         for(let i=0; i<bubbles; i++) {
             const bAngle = i * (Math.PI * 2 / bubbles) + progress * 2;
             const dist = r * 0.6;
             const bx = Math.cos(bAngle) * dist;
             const by = Math.sin(bAngle) * dist;
             const bSize = r * 0.3 * Math.sin(progress * 10 + i);

             ctx.globalAlpha = alpha * 0.3;
             ctx.beginPath(); ctx.arc(bx, by, Math.abs(bSize), 0, Math.PI*2); ctx.fill();
         }

         ctx.restore();

         // 4. Vertical "Heat" Haze (Not a pillar)
         ctx.globalCompositeOperation = 'lighter';
         const heatGrad = ctx.createLinearGradient(0, 0, 0, -300);
         heatGrad.addColorStop(0, p.color);
         heatGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = heatGrad;
         ctx.globalAlpha = alpha * 0.2;

         // Irregular shape
         ctx.beginPath();
         ctx.moveTo(-r/2, 0); 
         ctx.lineTo(-r/4, -300);
         ctx.lineTo(r/4, -300);
         ctx.lineTo(r/2, 0);
         ctx.fill();
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 
        // Chaos Shockwave = Jagged
        // Order Shockwave = Smooth Ring

        const r = progress * 300; 
        const width = 30 * (1 - progress);
        ctx.globalAlpha = (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;

        if (isChaos) {
            // Jagged
            ctx.globalCompositeOperation = 'source-over'; // Darker/Physical
            ctx.beginPath();
            const segs = 16;
            for(let i=0; i<=segs; i++) {
                const a = i * (Math.PI*2 / segs);
                const varR = r + (i%2===0 ? 20 : -20);
                const px = Math.cos(a)*varR;
                const py = Math.sin(a)*varR;
                if(i===0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.stroke();
        } else {
            // Smooth
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
        }
    }
};

import { GameEngine, Agent } from "../game";
import { GameEvent, Team } from "../../types";
import { HexUtils } from "../utils";
import { UNIT_VISUAL_HEIGHT, HUD_PADDING, UNIT_BODY_OFFSET } from "../../constants";

// Systems
import { VFXSystem } from "./vfx";
import { HUDSystem } from "./hud";
import { GridSystem } from "./grid";
import { CameraSystem } from "./CameraSystem";
import * as VFXSpawners from "./vfx/spawners";

const HUD_TEXT_OFFSET = UNIT_VISUAL_HEIGHT + HUD_PADDING + 20;
const KILL_STREAK_WINDOW = 12.0; 

export class VisualEventListener {
    private killStreaks = new Map<string, { count: number, lastTime: number }>();
    private firstBlood = false;

    public process(
        events: GameEvent[], 
        engine: GameEngine, 
        vfx: VFXSystem, 
        hud: HUDSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ) {
        if (engine.battleTime < 0.1) {
            this.killStreaks.clear();
            this.firstBlood = false;
        }

        events.forEach(event => {
            const hex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
            const terrainHeight = grid.getTerrainHeight(hex.q, hex.r, engine);
            const visualGroundY = event.pos.y - terrainHeight;

            // 1. HUD & Text
            if (['DAMAGE', 'HEAL', 'CC_APPLIED'].includes(event.type)) {
                 const baseY = visualGroundY - HUD_TEXT_OFFSET; 
                 let text = "";
                 let color = "#fff";
                 let size = 16;
                 let type: 'DAMAGE' | 'HEAL' | 'SHOUT' | 'CC' = 'DAMAGE';
                 let xOffset = 0;

                 if (event.type === 'DAMAGE') {
                     const val = Math.abs(event.value || 0);
                     text = val.toString();
                     const isCrit = val > 100;
                     color = isCrit ? '#ef4444' : '#fff'; 
                     size = isCrit ? 24 : 16;
                     type = 'DAMAGE';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else if (event.type === 'HEAL') {
                     text = "+" + Math.abs(event.value || 0);
                     color = '#4ade80';
                     type = 'HEAL';
                     xOffset = (Math.random() - 0.5) * 10;
                 } else {
                     text = event.text || "";
                     color = event.color || "#fff";
                     type = 'CC';
                     size = 14;
                     xOffset = -45;
                 }

                 if (text) hud.addFloatingText(event.pos.x + xOffset, baseY, text, color, size, type);

            } else if (event.type === 'CAST_START') {
                 if (event.skill && event.skill.tag !== 'BASIC') {
                     const isUlt = event.skill.tag === 'ULT';
                     const baseY = visualGroundY - HUD_TEXT_OFFSET - (isUlt ? 30 : 10); 
                     const xOffset = 55; 
                     hud.addFloatingText(event.pos.x + xOffset, baseY, event.skill.name, event.skill.color, 14, 'SHOUT', isUlt);
                 }
            } else if (event.type === 'CAST_FINISH') {
                 if (event.skill && event.skill.tag === 'ULT') {
                     // Only spawn instant impact logic here if it's not a projectile
                     // If it is projectile, the HIT event handles the big boom
                     if (event.skill.projectileSpeed === 0 || event.skill.power <= 0) {
                         camera.addTrauma(0.2); 
                     }
                 }
            } else if (event.type === 'KILL' && event.sourceId) {
                // ... (Kill Streak Logic kept same for brevity, it works fine) ...
                const now = engine.battleTime;
                const killer = event.sourceId;
                const killerAgent = engine.agents.find(a => a.id === killer);

                if (!this.firstBlood) {
                    this.firstBlood = true;
                    if (killerAgent) {
                        const kHex = HexUtils.fromPx(killerAgent.px, killerAgent.py, engine.mapConfig);
                        const kH = grid.getTerrainHeight(kHex.q, kHex.r, engine);
                        hud.addFloatingText(killerAgent.px, killerAgent.py - kH - HUD_TEXT_OFFSET - 60, "FIRST BLOOD", "#ef4444", 36, 'KILL_STREAK');
                        camera.addTrauma(0.3);
                    }
                }

                let streak = 1;
                const existing = this.killStreaks.get(killer);
                if (existing && now - existing.lastTime <= KILL_STREAK_WINDOW) streak = existing.count + 1;

                this.killStreaks.set(killer, { count: streak, lastTime: now });

                if (streak >= 2 && killerAgent) {
                    let streakText = "DOUBLE KILL";
                    let streakColor = "#cbd5e1";
                    if (streak === 3) { streakText = "TRIPLE KILL"; streakColor = "#fcd34d"; }
                    else if (streak === 4) { streakText = "QUADRA KILL"; streakColor = "#fb923c"; }
                    else if (streak >= 5) { streakText = "PENTA KILL"; streakColor = "#ef4444"; }

                    const kHex = HexUtils.fromPx(killerAgent.px, killerAgent.py, engine.mapConfig);
                    const kH = grid.getTerrainHeight(kHex.q, kHex.r, engine);
                    hud.addFloatingText(killerAgent.px, killerAgent.py - kH - HUD_TEXT_OFFSET - 40, streakText, streakColor, 32 + (streak * 4), 'KILL_STREAK');
                    camera.addTrauma(0.2 + streak * 0.1);
                }
            }

            // 3. VFX Handling
            switch (event.type) {
                case 'VISUAL_SLASH':
                    if (event.sourceId && event.targetId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        const target = engine.agents.find(a => a.id === event.targetId);
                        if (source && target) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                            const tHex = HexUtils.fromPx(target.px, target.py, engine.mapConfig);
                            const tH = grid.getTerrainHeight(tHex.q, tHex.r, engine);

                            VFXSpawners.spawnConnectorSlash(vfx, source.px, source.py - sH, target.px, target.py - tH, event.color || '#fff', event.skill?.visual || 'SLASH');
                        }
                    }
                    break;

                case 'DAMAGE': 
                    const dmg = Math.abs(event.value || 0);
                    // Standard hit spark
                    if (event.sourceId && event.targetId) {
                        const s = engine.agents.find(a => a.id === event.sourceId);
                        const t = engine.agents.find(a => a.id === event.targetId);
                        if (s && t) {
                            const bodyHeight = UNIT_BODY_OFFSET + t.physics.z;
                            const dx = t.px - s.px; const dy = t.py - s.py;
                            const len = Math.sqrt(dx*dx + dy*dy);
                            if (len > 0) {
                                const type = (event.skill?.visual === 'SLASH' || event.skill?.visual === 'SMASH') ? 'PHYSICAL' : 'MAGICAL';
                                VFXSpawners.spawnDirectionalImpact(vfx, event.pos.x, visualGroundY, bodyHeight, dx/len, dy/len, event.color || '#fff', type);
                            }
                        }
                    } else {
                        VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY, 25, 5, event.color || '#fff', 1.0, 0.8, 'SPARK');
                    }
                    if (dmg > 50) camera.addTrauma(0.15);
                    break;

                case 'VISUAL_BEAM':
                    if (event.sourceId) {
                        const source = engine.agents.find(a => a.id === event.sourceId);
                        if (source) {
                            const sHex = HexUtils.fromPx(source.px, source.py, engine.mapConfig);
                            const sH = grid.getTerrainHeight(sHex.q, sHex.r, engine);
                            VFXSpawners.spawnBeam(vfx, source.px, source.py - sH - 40, event.pos.x, visualGroundY - 30, event.color || '#fff');
                            VFXSpawners.spawnExplosion(vfx, event.pos.x, visualGroundY - 30, 0, 5, event.color || '#fff', 0.5, 0.5, 'SPARK');
                        }
                    }
                    break;

                case 'PROJECTILE_HIT': 
                    this.handleHitVisuals(event, engine, visualGroundY, vfx, grid, camera); 
                    break;

                case 'DEATH':
                    const dAgent = engine.agents.find(a => a.id === event.sourceId);
                    if (dAgent) VFXSpawners.spawnUnitShatter(vfx, event.pos.x, visualGroundY, dAgent.team, dAgent.role);
                    camera.addTrauma(0.3); 
                    break;

                case 'SPAWN':
                    VFXSpawners.spawnTeleport(vfx, event.pos.x, visualGroundY, event.color || '#fff');
                    break;

                case 'CAST_BREAK':
                    VFXSpawners.spawnDomainShatter(vfx, event.pos.x, event.pos.y, event.value || 1, event.color || '#fff');
                    camera.addTrauma(0.1);
                    break;
            }
        });
    }

    private handleHitVisuals(
        event: GameEvent, 
        engine: GameEngine, 
        visualY: number, 
        vfx: VFXSystem, 
        grid: GridSystem,
        camera: CameraSystem
    ): void {
        const color = event.skill?.color || '#fff';
        const isUlt = event.skill?.tag === 'ULT';
        const skill = event.skill;

        // Find Source Agent to determine Faction Style
        const source = engine.agents.find(a => a.id === event.sourceId);
        const faction = source ? source.team : Team.BLUE;

        const centerHex = HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig);
        const centerH = grid.getTerrainHeight(centerHex.q, centerHex.r, engine);
        const centerVisualY = event.pos.y - centerH;

        if (isUlt) {
            camera.addTrauma(0.5);

            // --- 1. CENTER PIECE: FACTION SPECIFIC RITUAL ---
            if (faction === Team.BLUE) {
                // Imperial: Divine Pillar (Order)
                // Spawn a clean, geometric pillar of light
                VFXSpawners.spawnDivinePillar(vfx, event.pos.x, centerVisualY, color, 1.5, 0);
                VFXSpawners.spawnShockwave(vfx, event.pos.x, centerVisualY, color, 1.2);
            } else {
                // Covenant: Hellgate (Chaos)
                // Spawn fissures, blood, and dark energy
                VFXSpawners.spawnBloodRitual(vfx, event.pos.x, centerVisualY, color, 1.5);
            }

            // --- 2. AOE RIPPLE: PER TILE SPLASH ---
            if (skill?.type === 'AOE') {
                const radius = skill.aoeRadius || 1;
                const affectedHexes = HexUtils.range(centerHex, radius);

                affectedHexes.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;

                        const dist = HexUtils.dist(centerHex, h);
                        // Delay creates the "Ripple" expanding outward
                        const delay = dist * 0.08; 

                        // Spawn a sub-effect on this specific tile
                        VFXSpawners.spawnGridImpact(vfx, tilePos.x, tileVisualY, color, faction, delay);

                        // --- 3. PERSISTENT FIELD EFFECTS (SMOKE/FIRE) ---
                        // If skill has DoT, spawn lingering particles
                        if (skill.ccType === 'DOT' || skill.ccType === 'SILENCE') {
                            VFXSpawners.spawnLingeringField(vfx, tilePos.x, tileVisualY, color, skill.ccType, 4.0, delay);
                        }
                    }
                });
            } else {
                // Single Target Ult Explosion
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 0, 40, color, 1.2, 0.8, 'SPARK');
            }
        } else {
            // Normal Skill Logic
            if (skill?.type === 'AOE') {
                const radius = skill.aoeRadius || 1;
                const affected = HexUtils.range(centerHex, radius);

                // Add Decal at center
                VFXSpawners.addDecal(vfx, event.pos.x, centerVisualY, color);

                affected.forEach(h => {
                    if (engine.isValid(h.q, h.r)) {
                        const tileH = grid.getTerrainHeight(h.q, h.r, engine);
                        const tilePos = HexUtils.toPx(h.q, h.r, engine.mapConfig);
                        const tileVisualY = tilePos.y - tileH;
                        const dist = HexUtils.dist(centerHex, h);

                        // Smaller ripple for normal skills
                        if (dist <= radius) {
                            if (Math.random() < 0.6) { // Not every tile needs a heavy hit for basics
                                VFXSpawners.addImpact(vfx, tilePos.x, tileVisualY, 0, color, 'RING', 0.4);
                            }
                            if (skill.ccType === 'DOT') {
                                VFXSpawners.spawnLingeringField(vfx, tilePos.x, tileVisualY, color, skill.ccType, 3.0, dist * 0.05);
                            }
                        }
                    }
                });
            } else {
                // Single hit
                VFXSpawners.addImpact(vfx, event.pos.x, visualY, 30, color, 'RING', 0.6);
                VFXSpawners.spawnExplosion(vfx, event.pos.x, visualY, 30, 12, color, 1.0, 0.5, 'SPARK');
            }
        }
    }
}

import { Particle } from "../state";
import { isChaosStyle, normalizeHex } from "../utils";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.save();

        // Shared translation
        ctx.translate(p.x, p.y);

        if (p.type === 'SPRITE') {
            if (p.image) {
                const alpha = Math.min(1, (1 - progress) * 5); 
                ctx.globalAlpha = alpha;
                if (p.z < 20) {
                    ctx.save();
                    ctx.translate(0, p.z);
                    ctx.scale(1, 0.5);
                    ctx.fillStyle = 'rgba(0,0,0,0.3)';
                    ctx.beginPath(); ctx.arc(0, 0, p.size/3, 0, Math.PI*2); ctx.fill();
                    ctx.restore();
                }
                ctx.rotate(p.rotation);
                const scale = p.size / 64; 
                ctx.scale(scale, scale);
                ctx.drawImage(p.image, -p.image.width/2, -p.image.height/2);
            }

        } else if (p.type === 'CHIP') {
            ctx.rotate(p.rotation); 
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - Math.pow(progress, 4);
            const s = p.size;
            ctx.beginPath();
            ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            ctx.fill();

        } else if (p.type === 'SHARD') {
            ctx.rotate(p.rotation);
            ctx.fillStyle = p.color;
            ctx.beginPath();
            const s = p.size;
            ctx.moveTo(-s, -s/2); ctx.lineTo(0, -s); ctx.lineTo(s, -s/2); ctx.lineTo(0, s);
            ctx.fill();
            ctx.strokeStyle = 'rgba(255,255,255,0.4)';
            ctx.lineWidth = 1;
            ctx.stroke();

        } else if (p.type === 'SMOKE') {
            const r = p.size * (0.5 + progress * 2); 
            // Softer Alpha
            ctx.globalAlpha = (1 - progress) * 0.3;
            ctx.fillStyle = p.color; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'BLAST') {
            ctx.scale(1, 0.55); 
            const r = p.size * (progress * 2); 
            ctx.globalCompositeOperation = 'lighter';
            ctx.strokeStyle = p.color;
            ctx.lineWidth = (1 - progress) * 5; 
            ctx.globalAlpha = (1 - progress) * 0.8;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'BEAM') {
            if (p.targetX !== undefined && p.targetY !== undefined) {
                ctx.translate(-p.x, -p.y); 
                ctx.globalCompositeOperation = 'lighter';
                const sx = p.x; const sy = p.y;
                const tx = p.targetX; const ty = p.targetY;

                if (isChaos) {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = 3;
                    ctx.beginPath();
                    ctx.moveTo(sx, sy);
                    const segs = 10;
                    const dx = tx - sx; const dy = ty - sy;
                    for(let i=1; i<segs; i++) {
                        const ratio = i/segs;
                        const jit = (Math.random()-0.5) * 20;
                        ctx.lineTo(sx + dx * ratio + jit, sy + dy * ratio + jit);
                    }
                    ctx.lineTo(tx, ty);
                    ctx.stroke();
                    ctx.lineWidth = 1; ctx.strokeStyle = '#000'; ctx.stroke();
                } else {
                    ctx.strokeStyle = p.color;
                    ctx.lineWidth = (1 - Math.abs(progress - 0.5)*2) * 8;
                    ctx.lineCap = 'round';
                    ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(tx, ty); ctx.stroke();
                    ctx.lineWidth /= 2; ctx.strokeStyle = '#fff'; ctx.stroke();
                }
            }
        } else if (p.type === 'RING') {
            ctx.scale(1, 0.55); 
            const r = progress * 40;
            ctx.strokeStyle = p.color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1 - progress;
            // Removed 'lighter' to reduce exposure, standard alpha blend
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();

        } else if (p.type === 'SPARK') {
            const r = p.size;
            ctx.fillStyle = p.color;
            ctx.globalAlpha = 1 - Math.pow(progress, 3); 
            ctx.globalCompositeOperation = 'lighter'; 
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

        } else if (p.type === 'DEBRIS') {
            ctx.fillStyle = p.color;
            ctx.rotate(p.rotation);
            ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size);

        } else if (p.type === 'PILLAR') {
            ctx.translate(0, -20); 
            this.drawDivinePillar(ctx, p, progress);
        } else if (p.type === 'SHOCKWAVE') {
            ctx.translate(0, -20);
            this.drawShockwave(ctx, p, progress, isChaos);
        } else if (p.type === 'DOMAIN') {
            ctx.translate(0, -20);
            this.drawBloodRitual(ctx, p, progress);
        }

        ctx.restore();
    },

    // 🏛️ BLUE: DIVINE PILLAR (ORDER)
    // Enhanced: Faster flow, central core beam, energetic fade
    drawDivinePillar(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
        const lifeRatio = p.life / p.maxLife;
        let alpha = 0;
        // Sharper fade in/out for impact
        if (lifeRatio > 0.8) alpha = (1 - lifeRatio) * 5; 
        else if (lifeRatio < 0.2) alpha = lifeRatio * 5; 
        else alpha = 1.0;

        const height = 1500; // Even taller
        const width = p.size;

        ctx.save();
        ctx.scale(1, 0.55); 

        // 1. Ground Energy Ring (Impact Zone)
        ctx.globalCompositeOperation = 'lighter';
        ctx.strokeStyle = p.color;
        ctx.lineWidth = 4 * alpha;
        ctx.globalAlpha = alpha * 0.8;
        ctx.beginPath(); ctx.arc(0, 0, width, 0, Math.PI*2); ctx.stroke();

        // 2. Rising Energy Rings (Faster Speed)
        ctx.lineWidth = 2;
        const ringCount = 4;
        for(let i=0; i<ringCount; i++) {
            // Speed up the flow
            const ringH = ((progress * 8 + i) % ringCount) * 150;
            const ringAlpha = (1 - ringH/600) * alpha;
            ctx.globalAlpha = ringAlpha * 0.6;
            ctx.beginPath(); ctx.ellipse(0, -ringH * 2, width * (1 - ringH/1000), width * (1 - ringH/1000), 0, 0, Math.PI*2); ctx.stroke();
        }

        ctx.restore();

        // 3. The Pillar Core (Intense Beam)
        ctx.globalCompositeOperation = 'lighter';

        // A. Wide Soft Glow
        const softGrad = ctx.createLinearGradient(0, 0, 0, -height);
        softGrad.addColorStop(0, p.color);
        softGrad.addColorStop(0.5, 'transparent');
        ctx.fillStyle = softGrad;
        ctx.globalAlpha = alpha * 0.3; 
        ctx.fillRect(-width * 0.8, -height, width * 1.6, height);

        // B. Hard Inner Core (White Hot)
        const coreGrad = ctx.createLinearGradient(0, 0, 0, -height);
        coreGrad.addColorStop(0, '#ffffff');
        coreGrad.addColorStop(0.3, p.color);
        coreGrad.addColorStop(1, 'transparent');
        ctx.fillStyle = coreGrad;
        ctx.globalAlpha = alpha * 0.6;
        ctx.fillRect(-width * 0.2, -height, width * 0.4, height);

        // C. Rising Particles (Sparkles inside)
        ctx.fillStyle = '#fff';
        const sparkCount = 10;
        for(let i=0; i<sparkCount; i++) {
            const sparkY = -((progress * 20 + i) % 10) * 100;
            const sparkX = (Math.sin(i * 132) * width * 0.3);
            const sAlpha = (1 - Math.abs(sparkY)/800) * alpha;
            ctx.globalAlpha = sAlpha;
            ctx.beginPath(); ctx.rect(sparkX, sparkY, 4, 20); ctx.fill();
        }
    },

    // 🩸 RED: BLOOD RITUAL (CHAOS)
    drawBloodRitual(ctx: CanvasRenderingContext2D, p: Particle, progress: number) {
         const lifeRatio = p.life / p.maxLife;
         const alpha = Math.sin(lifeRatio * Math.PI); 
         const r = p.size;

         ctx.save();
         ctx.scale(1, 0.55); 

         // 1. The Void (Ground Hole)
         ctx.globalCompositeOperation = 'source-over'; 
         const voidGrad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
         voidGrad.addColorStop(0, '#000'); // Black center
         voidGrad.addColorStop(0.7, '#220000');
         voidGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = voidGrad;
         ctx.globalAlpha = alpha * 0.9;
         ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();

         // 2. Cracks / Runes
         ctx.strokeStyle = p.color; // Red/Orange
         ctx.lineWidth = 3;
         ctx.globalAlpha = alpha;
         ctx.beginPath();
         // Jagged lines from center
         for(let i=0; i<6; i++) {
             const angle = i * (Math.PI/3) + progress;
             ctx.moveTo(0,0);
             ctx.lineTo(Math.cos(angle)*r, Math.sin(angle)*r);
         }
         ctx.stroke();

         // 3. Rising Dark Miasma (Noise)
         ctx.globalCompositeOperation = 'lighter'; // Glowy smoke
         ctx.fillStyle = p.color;
         const bubbles = 5;
         for(let i=0; i<bubbles; i++) {
             const bAngle = i * (Math.PI * 2 / bubbles) + progress * 2;
             const dist = r * 0.6;
             const bx = Math.cos(bAngle) * dist;
             const by = Math.sin(bAngle) * dist;
             const bSize = r * 0.3 * Math.sin(progress * 10 + i);

             ctx.globalAlpha = alpha * 0.3;
             ctx.beginPath(); ctx.arc(bx, by, Math.abs(bSize), 0, Math.PI*2); ctx.fill();
         }

         ctx.restore();

         // 4. Vertical "Heat" Haze (Not a pillar)
         ctx.globalCompositeOperation = 'lighter';
         const heatGrad = ctx.createLinearGradient(0, 0, 0, -300);
         heatGrad.addColorStop(0, p.color);
         heatGrad.addColorStop(1, 'transparent');
         ctx.fillStyle = heatGrad;
         ctx.globalAlpha = alpha * 0.2;

         // Irregular shape
         ctx.beginPath();
         ctx.moveTo(-r/2, 0); 
         ctx.lineTo(-r/4, -300);
         ctx.lineTo(r/4, -300);
         ctx.lineTo(r/2, 0);
         ctx.fill();
    },

    drawShockwave(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean) {
        ctx.scale(1, 0.55); 
        // Chaos Shockwave = Jagged
        // Order Shockwave = Smooth Ring

        const r = progress * 300; 
        const width = 30 * (1 - progress);
        ctx.globalAlpha = (1 - progress);
        ctx.strokeStyle = p.color;
        ctx.lineWidth = width;

        if (isChaos) {
            // Jagged
            ctx.globalCompositeOperation = 'source-over'; // Darker/Physical
            ctx.beginPath();
            const segs = 16;
            for(let i=0; i<=segs; i++) {
                const a = i * (Math.PI*2 / segs);
                const varR = r + (i%2===0 ? 20 : -20);
                const px = Math.cos(a)*varR;
                const py = Math.sin(a)*varR;
                if(i===0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.stroke();
        } else {
            // Smooth
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.stroke();
        }
    }
};

import { GameEngine } from "../../../game";
import { Vector, HexUtils } from "../../../utils";
import { AssetManager } from "../../../assets";
import { RenderableItem } from "../../grid";
import { getTransitionOffset, isChaosStyle } from "../utils";

const UNIT_CHEST_HEIGHT = 40;

export const ProjectileRenderer = {
    collect(
        engine: GameEngine,
        getTerrainHeight: (q: number, r: number) => number,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        engine.projectiles.forEach(p => {
             const offsetP = getTransitionOffset(p.x, p.y, engine.mapConfig, transitionT, transitionPhase);
             if (offsetP > 500) return;

             let hStart = 0, hEnd = 0;
             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             if (getTerrainHeight && engine.mapConfig) {
                 const startHex = HexUtils.fromPx(p.startX, p.startY, engine.mapConfig);
                 const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig);
                 hStart = getTerrainHeight(startHex.q, startHex.r);
                 hEnd = getTerrainHeight(targetHex.q, targetHex.r);
             }

             // Calculate Visual Position with Arcing/Wobble
             const getVisualPos = (lx: number, ly: number, flightProgress: number) => {
                 const t = flightProgress;
                 // Trajectory Height: Interpolated line between shooter and target
                 const trajectoryTerrainHeight = hStart + (hEnd - hStart) * t;

                 // Actual Ground Height: Look up what's directly underneath the projectile now
                 const currentHex = HexUtils.fromPx(lx, ly, engine.mapConfig);
                 const groundHeight = getTerrainHeight(currentHex.q, currentHex.r);

                 let arcOffset = 0;

                 // TYPE 1: PHYSICAL ARC (Arrow, Bomb) - Gravity based
                 if (p.skill.visual === 'ARROW' || p.skill.visual === 'BOMB') {
                     // High arc for bombs, shallow for arrows
                     const arcHeight = p.skill.visual === 'BOMB' ? 250 : 80; 
                     // Parabola: 4 * h * t * (1-t)
                     arcOffset = 4 * arcHeight * t * (1 - t);
                 } 
                 // TYPE 2: MAGICAL (Bolt, Fireball) - Wobble/Straight
                 else if (p.skill.visual === 'BOLT' || p.skill.visual === 'FIREBALL') {
                     // Sine wave wobble based on distance traveled
                     const wobbleFreq = 0.2; 
                     const wobbleAmp = 10;
                     arcOffset = Math.sin(lx * wobbleFreq + ly * wobbleFreq) * wobbleAmp;
                 }

                 const off = getTransitionOffset(lx, ly, engine.mapConfig, transitionT, transitionPhase);

                 return {
                     x: lx,
                     // Projectile follows trajectory + arc
                     y: ly - trajectoryTerrainHeight - UNIT_CHEST_HEIGHT - arcOffset + off,
                     // Shadow sticks to the ACTUAL ground
                     shadowY: ly - groundHeight + off
                 };
             };

             const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y});
             const progress = Math.min(1, Math.max(0, currentDist / totalDist));
             const headVis = getVisualPos(p.x, p.y, progress);

             // Look-Ahead Rotation Calculation
             const lookAheadDist = 10;
             const rawDir = Vector.normalize(Vector.sub(p.targetPos, {x: p.startX, y: p.startY}));
             const nextLx = p.x + rawDir.x * lookAheadDist;
             const nextLy = p.y + rawDir.y * lookAheadDist;
             const nextProgress = Math.min(1, Math.max(0, Vector.dist({x: p.startX, y: p.startY}, {x: nextLx, y: nextLy}) / totalDist));

             const nextVis = getVisualPos(nextLx, nextLy, nextProgress);

             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);
             const spin = p.skill.visual === 'BOMB' ? (progress * 15) : 0;

             const isChaos = isChaosStyle(p.skill.color);

             list.push({
                 y: p.y + 50 + offsetP, z: 20, 
                 draw: (ctx) => {
                    // --- 1. Draw Trail ---
                    if (p.trail.length > 1) {
                        ctx.save();

                        if (p.skill.visual === 'ARROW') {
                            ctx.beginPath();
                            const tail = p.trail[0];
                            const tailDist = Vector.dist({x: p.startX, y: p.startY}, tail);
                            const tailVis = getVisualPos(tail.x, tail.y, tailDist/totalDist);
                            ctx.moveTo(tailVis.x, tailVis.y);
                            ctx.lineTo(headVis.x, headVis.y);

                            ctx.strokeStyle = `rgba(255, 255, 255, 0.4)`;
                            ctx.lineWidth = 1;
                            ctx.stroke();
                        } else {
                            ctx.lineCap = 'round';
                            ctx.lineJoin = 'round';
                            ctx.globalCompositeOperation = 'lighter';

                            const trailPoints = p.trail.map(t => {
                                const d = Vector.dist({x: p.startX, y: p.startY}, t);
                                return getVisualPos(t.x, t.y, d/totalDist);
                            });
                            trailPoints.push(headVis);

                            for (let i = 0; i < trailPoints.length - 1; i++) {
                                const pt = trailPoints[i];
                                const next = trailPoints[i+1];
                                const ratio = i / (trailPoints.length - 1); 

                                const baseWidth = (p.skill.visual === 'FIREBALL' || p.skill.visual === 'SMASH') ? 24 : 12;
                                ctx.lineWidth = baseWidth * ratio;
                                ctx.strokeStyle = p.skill.color;

                                ctx.beginPath();
                                ctx.moveTo(pt.x, pt.y);
                                ctx.lineTo(next.x, next.y);

                                if (isChaos) {
                                    ctx.globalAlpha = ratio * 0.8; 
                                } else {
                                    ctx.globalAlpha = ratio * 0.5;
                                }
                                ctx.stroke();

                                if (!isChaos) {
                                    ctx.lineWidth = baseWidth * ratio * 0.3;
                                    ctx.strokeStyle = '#fff';
                                    ctx.stroke();
                                }
                            }
                        }
                        ctx.restore();
                    }

                    // --- 2. Draw Shadow ---
                    // Only draw shadow if we are decently above ground to avoid clutter
                    const altitude = headVis.shadowY - headVis.y;
                    if (altitude > 5) {
                        ctx.save();
                        ctx.translate(headVis.x, headVis.shadowY);
                        // Make shadow shrink as projectile goes higher
                        const shadowScale = Math.max(0.2, 1 - altitude/400);
                        ctx.scale(shadowScale, shadowScale);
                        ctx.fillStyle = 'rgba(0,0,0,0.3)';
                        ctx.beginPath(); ctx.ellipse(0, 0, 12, 6, 0, 0, Math.PI*2); ctx.fill();
                        ctx.restore();
                    }

                    // --- 3. Draw Projectile Head ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.y);
                    if (p.skill.visual === 'BOMB') ctx.rotate(spin);
                    else ctx.rotate(angle);

                    const img = AssetManager.getProjectile(p.skill.visual || 'BOLT', p.skill.color);
                    if (img && img.width > 0) {
                        ctx.drawImage(img, -48, -32, 96, 64);
                    }
                    ctx.restore();
                 }
             });
        });

        return list;
    }
};

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { SpriteManager } from "../../sprites";
import { Team } from "../../../types";

// =================================================================================
// 🧚 UNIT VISUAL EFFECTS (Flight, Casting, Status)
// =================================================================================

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171'; // Blue-400 : Red-400

    // We are at Ground Level (0,0).
    // Unit Feet are at (physX, physY - physZ).

    const feetX = physX;
    const feetY = physY - physZ; 

    ctx.save();

    // 1. Ground Shadow / Rune (Projection Source)
    // No more solid column. Just a projection mark on the ground.
    ctx.globalAlpha = 0.6;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;

    // Scale shadow based on height to give depth cue
    // Higher = Smaller shadow
    const heightRatio = Math.max(0.5, 1 - Math.abs(physZ) / 300);
    ctx.scale(heightRatio, heightRatio);

    ctx.beginPath();
    ctx.ellipse(0, 0, 20, 10, 0, 0, Math.PI * 2);
    ctx.stroke();

    // Rotating crosshair
    ctx.save();
    ctx.rotate(t);
    ctx.lineWidth = 1;
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.arc(0, 0, 15, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();

    // 2. Faint Connection Line (Optional, very subtle holographic tether)
    // Only visible if very high up to help tracking
    if (Math.abs(physZ) > 60) {
        ctx.restore(); // Reset scale
        ctx.save();
        ctx.globalAlpha = 0.15;
        ctx.setLineDash([4, 8]);
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(feetX, feetY);
        ctx.stroke();
    }

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 

    ctx.save();
    ctx.translate(0, 5); // Just below body
    ctx.scale(1, 0.5); 

    // Rotating Wind/Energy Swirl at Feet
    ctx.rotate(t * 8); // Faster spin for thrusters

    // Inner Turbine Ring
    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.6;
    ctx.stroke();

    // Outer Thruster Arcs
    ctx.beginPath();
    // 3 Arcs for stability look
    for(let i=0; i<3; i++) {
        const offset = i * (Math.PI * 2 / 3);
        const arcLen = Math.PI / 2;
        ctx.moveTo(Math.cos(offset) * 18, Math.sin(offset) * 18);
        ctx.arc(0, 0, 18, offset, offset + arcLen);
    }

    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.5 + Math.sin(t * 20) * 0.2; // Flicker
    ctx.stroke();

    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    // 1. Rising Energy Lines
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 3; 
    const lineCount = 5 + Math.floor(progress * 8); 
    for(let i=0; i<lineCount; i++) {
        const h = (t * 150 + i * 40) % 90; 
        const alpha = 1 - (h / 90);
        const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
    }

    // 2. Converging Rings
    if (progress > 0.2) {
        const ringScale = (1 - progress) * 2.5; 
        ctx.globalAlpha = progress;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

        ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
        ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. Hand Glow
    ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

    // 4. Final Flash
    if (progress > 0.9) {
        ctx.globalAlpha = (progress - 0.9) * 10;
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
    }

    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, -110);

            const glow = AssetManager.getGlowSprite(skill.color);
            ctx.globalCompositeOperation = 'lighter';
            const pulse = 0.5 + Math.sin(t * 10) * 0.1;
            ctx.globalAlpha = 0.3 * pulse;
            ctx.drawImage(glow, -40, -40, 80, 80);

            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    const HEAD_Y = -60; 

    // 1. FROZEN - ICE PRISM (Encasing the unit)
    if (agent.visualStatus === 'FROZEN') {
        ctx.save();
        ctx.translate(0, -40); // Center of body

        // Draw Hexagonal Prism
        const w = 30;
        const h = 50;

        ctx.globalCompositeOperation = 'source-over';
        // Back Faces
        ctx.fillStyle = 'rgba(186, 230, 253, 0.4)'; // Light Blue
        ctx.beginPath();
        ctx.moveTo(-w, -h); ctx.lineTo(w, -h); ctx.lineTo(w, h); ctx.lineTo(-w, h);
        ctx.fill();

        // Front Faces (Glassy)
        const grad = ctx.createLinearGradient(-w, -h, w, h);
        grad.addColorStop(0, 'rgba(255,255,255,0.6)');
        grad.addColorStop(0.5, 'rgba(56, 189, 248, 0.3)');
        grad.addColorStop(1, 'rgba(14, 165, 233, 0.5)');

        ctx.fillStyle = grad;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;

        ctx.beginPath();
        ctx.moveTo(0, -h - 10); // Top Tip
        ctx.lineTo(w + 5, -h + 10);
        ctx.lineTo(w, h);
        ctx.lineTo(0, h + 10); // Bottom Tip
        ctx.lineTo(-w, h);
        ctx.lineTo(-w - 5, -h + 10);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Glint
        ctx.globalCompositeOperation = 'lighter';
        ctx.beginPath();
        ctx.moveTo(0, -h-10); ctx.lineTo(0, h+10);
        ctx.strokeStyle = 'rgba(255,255,255,0.5)';
        ctx.stroke();

        ctx.restore();
    }

    // 2. BANISH - GHOSTLY CAGE (Rotates around unit)
    if (agent.banished && agent.visualStatus !== 'POLYMORPH') {
        ctx.translate(0, -30); // Body center

        ctx.globalCompositeOperation = 'source-over';
        ctx.strokeStyle = '#c084fc';
        ctx.lineWidth = 3;
        ctx.globalAlpha = 0.8;

        // Vertical Bars orbiting (Simulated 3D Cylinder)
        const bars = 5;
        const radius = 25;
        const height = 50;

        for(let i=0; i<bars; i++) {
            // Rotate bars over time
            const angle = t * 2 + (i / bars) * Math.PI * 2;
            const x = Math.cos(angle) * radius;
            const z = Math.sin(angle); // Depth

            // Perspective scale
            const scale = 1 + z * 0.1;
            const alpha = 0.5 + (z + 1) * 0.25; // Fade back bars

            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(x, -height);
            ctx.lineTo(x, height);
            ctx.stroke();

            // Runes on bars
            if (i % 2 === 0) {
                ctx.fillStyle = '#d8b4fe';
                ctx.beginPath(); ctx.arc(x, -height/2 + Math.sin(t*3+i)*10, 3, 0, Math.PI*2); ctx.fill();
            }
        }

        // Top and Bottom Rings
        ctx.globalAlpha = 0.6;
        ctx.save();
        ctx.scale(1, 0.3); // Isometric
        ctx.beginPath(); ctx.arc(0, -height / 0.3, radius, 0, Math.PI*2); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, height / 0.3, radius, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. STUN - 3D DIZZY RING
    if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
        ctx.translate(0, HEAD_Y - 10);

        ctx.globalCompositeOperation = 'lighter';
        ctx.lineWidth = 3;

        const count = 5;
        const radius = 25;

        // Orbiting Stars
        for(let i=0; i<count; i++) {
            const angle = t * 4 + (i / count) * Math.PI * 2;
            // 3D Orbit: Y is squashed
            const x = Math.cos(angle) * radius;
            const y = Math.sin(angle) * radius * 0.3;
            // Z-sort simulation: if sin(angle) > 0, it's in front
            const scale = 1 + Math.sin(angle) * 0.3;

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(scale, scale);

            ctx.fillStyle = '#facc15';
            ctx.shadowColor = '#fbbf24';
            ctx.shadowBlur = 10;

            // Draw Star
            ctx.beginPath();
            const starPts = 5;
            for(let j=0; j<starPts*2; j++) {
                const r = j%2===0 ? 6 : 2;
                const a = j * Math.PI / starPts;
                ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
            }
            ctx.fill();
            ctx.restore();
        }
    }

    // 4. SILENCE - FLOATING RUNE SEAL
    if (agent.silenceTimer > 0) {
        ctx.translate(0, HEAD_Y - 15);

        const scale = 1 + Math.sin(t * 5) * 0.1;
        ctx.scale(scale, scale);

        ctx.fillStyle = '#1e1b4b'; 
        ctx.strokeStyle = '#a855f7';
        ctx.lineWidth = 2;
        ctx.shadowColor = '#c084fc';
        ctx.shadowBlur = 10;

        // Rune Box
        ctx.beginPath();
        ctx.rect(-15, -10, 30, 20);
        ctx.fill();
        ctx.stroke();

        // "X" or Rune Text
        ctx.beginPath();
        ctx.moveTo(-8, -5); ctx.lineTo(8, 5);
        ctx.moveTo(8, -5); ctx.lineTo(-8, 5);
        ctx.stroke();
    }

    // 5. DoT - Rising Bubbles / Smoke
    if (agent.dotTimer > 0) {
        ctx.translate(0, -40);
        const count = 3;
        for(let i=0; i<count; i++) {
            const phase = (t + i/count) % 1;
            const y = -phase * 40;
            const x = Math.sin(phase * 10 + i) * 10;
            const size = (1-phase) * 6;

            ctx.fillStyle = i%2===0 ? '#10b981' : '#a855f7'; 
            ctx.globalAlpha = (1-phase);
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
    }

    // 6. HoT - Spiraling +
    if (agent.hotTimer > 0) {
        ctx.translate(0, -30);
        const angle = -t * 3;
        const radius = 25;

        const x = Math.cos(angle) * radius;
        const y = Math.sin(angle) * radius * 0.3; // Flattened

        ctx.fillStyle = '#4ade80';
        ctx.font = 'bold 16px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('+', x, y);
    }

    ctx.restore();
}

export function drawSpawnIndicator(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, scale: number) {
    const assets = SpriteManager.getUnitImages(agent.role, agent.team);
    const totalDuration = 0.5;
    const alpha = Math.max(0, agent.spawnTimer / totalDuration);
    const yOffset = -85 * scale; 

    ctx.save();
    ctx.translate(x, y + yOffset);
    const popScale = 1.0 + alpha * 0.2;
    ctx.scale(popScale, popScale);
    ctx.globalAlpha = alpha;

    ctx.fillStyle = 'rgba(15, 23, 42, 0.4)'; 
    ctx.strokeStyle = agent.team === Team.BLUE ? 'rgba(59, 130, 246, 0.8)' : 'rgba(239, 68, 68, 0.8)';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI*2); ctx.fill(); ctx.stroke();

    ctx.drawImage(assets.icon, -12, -12, 24, 24);

    ctx.font = 'bold 10px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = 'rgba(0,0,0,0.8)';
    ctx.lineWidth = 2;
    ctx.strokeText(agent.role, 0, 28);
    ctx.fillText(agent.role, 0, 28);

    ctx.restore();
}

import { GameEngine, Agent } from "../game";
import { Role, Team, Skill, AnimState } from "../../types";
import { UNIT_DB } from "../../data/units";
import { COLORS } from "../../constants";
import { HexUtils } from "../utils";

export class AgentManager {
    constructor() {}

    public addAgent(engine: GameEngine, team: Team, q: number, r: number, hpOverride?: number): Agent | null {
        if (!engine.map.isValid(q, r) || engine.map.isBlocked(q, r, engine)) return null;

        const a = new Agent(team, q, r, engine.mapConfig);

        // Smart Role Selection Strategy
        // Count existing roles in the team to maintain composition balance
        const allRoles = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
        const teamAgents = engine.agents.filter(ag => ag.team === team);
        const roleCounts = new Map<Role, number>();
        allRoles.forEach(role => roleCounts.set(role, 0));
        teamAgents.forEach(ag => roleCounts.set(ag.role, (roleCounts.get(ag.role) || 0) + 1));

        // Find roles with minimum count
        let minCount = 999;
        roleCounts.forEach(c => { if(c < minCount) minCount = c; });

        const candidates = allRoles.filter(role => roleCounts.get(role) === minCount);
        a.role = candidates[Math.floor(Math.random() * candidates.length)];

        // ID Generation
        const suffix = Math.random().toString(36).substr(2, 4).toUpperCase();
        a.id = `${a.role}-${suffix}`;

        // Apply Base Stats from DB
        const stats = UNIT_DB[a.role];
        a.maxHp = hpOverride || stats.maxHp;
        a.hp = a.maxHp;
        a.maxMp = stats.maxMp;
        a.moveSpeed = stats.moveSpeed; 

        // Critical Fix: Copy Physics/Movement properties
        a.movementType = stats.movementType;
        a.jump = stats.jump;
        a.weight = stats.weight;

        // Skill Selection: 1 Ult, 1 Active, 1 Basic
        const validSkills = engine.skillDB.filter(s => s.role === a.role && (s.team === undefined || s.team === team));
        const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;

        a.skillIds = [
            rnd(validSkills.filter(s => s.tag === 'ULT')),
            rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
            rnd(validSkills.filter(s => s.tag === 'BASIC'))
        ];

        // Spawn Effect
        a.spawnTimer = 0.5;
        engine.events.push({ 
            type: 'SPAWN', 
            pos: { x: a.px, y: a.py },
            color: COLORS[team],
            sourceId: a.id
        });

        // Register
        engine.agents.push(a);
        engine.agentMap.set(HexUtils.hash(q, r), a);

        return a;
    }

    public handleDeadState(a: Agent, engine: GameEngine) {
        if (a.fullyDead) return;

        if (!a.deadLogged) {
            engine.log(a, '死亡', null, '陣亡');

            // Push Event: Renderer will handle the visual explosion (Shatter)
            engine.events.push({ 
                type: 'DEATH', 
                pos: {x: a.px, y: a.py}, 
                sourceId: a.id,
                team: a.team // Pass team for color coding debris
            });

            a.deadLogged = true;
            a.setAnim(AnimState.DEAD);

            // Remove from spatial map so others can walk here
            engine.agentMap.delete(HexUtils.hash(a.q, a.r));

            // INSTANT VANISH: logic is done, body is hidden, particles take over
            a.fullyDead = true; 
            a.visualStatus = 'NONE';
            a.isMoving = false; 
            a.path = [];
        }
    }
}

import { GameEngine } from "../../../game";
import { Vector, HexUtils } from "../../../utils";
import { AssetManager } from "../../../assets";
import { RenderableItem } from "../../grid";
import { getTransitionOffset, isChaosStyle } from "../utils";

const UNIT_CHEST_HEIGHT = 40;

export const ProjectileRenderer = {
    collect(
        engine: GameEngine,
        getTerrainHeight: (q: number, r: number) => number,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        engine.projectiles.forEach(p => {
             const offsetP = getTransitionOffset(p.x, p.y, engine.mapConfig, transitionT, transitionPhase);
             if (offsetP > 500) return;

             let hStart = 0, hEnd = 0;
             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             if (getTerrainHeight && engine.mapConfig) {
                 const startHex = HexUtils.fromPx(p.startX, p.startY, engine.mapConfig);
                 const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig);
                 hStart = getTerrainHeight(startHex.q, startHex.r);
                 hEnd = getTerrainHeight(targetHex.q, targetHex.r);
             }

             // Calculate Visual Position with Arcing/Wobble
             const getVisualPos = (lx: number, ly: number, flightProgress: number) => {
                 const t = flightProgress;
                 // Trajectory Height: Interpolated line between shooter and target
                 const trajectoryTerrainHeight = hStart + (hEnd - hStart) * t;

                 // Actual Ground Height: Look up what's directly underneath the projectile now
                 const currentHex = HexUtils.fromPx(lx, ly, engine.mapConfig);
                 const groundHeight = getTerrainHeight(currentHex.q, currentHex.r);

                 let arcOffset = 0;

                 // TYPE 1: PHYSICAL ARC (Arrow, Bomb) - Gravity based
                 if (p.skill.visual === 'ARROW' || p.skill.visual === 'BOMB') {
                     // Dynamic Arc Height: Scale based on distance to avoid ICBM effect on short shots
                     // Min arc 10, max arc 150 + bonus for Bombs
                     const distFactor = Math.min(150, totalDist * 0.25);
                     const baseArc = p.skill.visual === 'BOMB' ? 100 : 20;
                     const arcHeight = baseArc + distFactor;

                     // Parabola: 4 * h * t * (1-t)
                     arcOffset = 4 * arcHeight * t * (1 - t);
                 } 
                 // TYPE 2: MAGICAL (Bolt, Fireball) - Wobble/Straight
                 else if (p.skill.visual === 'BOLT' || p.skill.visual === 'FIREBALL') {
                     // Sine wave wobble based on distance traveled
                     const wobbleFreq = 0.2; 
                     const wobbleAmp = 10;
                     arcOffset = Math.sin(lx * wobbleFreq + ly * wobbleFreq) * wobbleAmp;
                 }

                 const off = getTransitionOffset(lx, ly, engine.mapConfig, transitionT, transitionPhase);

                 return {
                     x: lx,
                     // Projectile follows trajectory + arc
                     y: ly - trajectoryTerrainHeight - UNIT_CHEST_HEIGHT - arcOffset + off,
                     // Shadow sticks to the ACTUAL ground
                     shadowY: ly - groundHeight + off
                 };
             };

             const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y});
             const progress = Math.min(1, Math.max(0, currentDist / totalDist));
             const headVis = getVisualPos(p.x, p.y, progress);

             // Look-Ahead Rotation Calculation
             const lookAheadDist = 10;
             const rawDir = Vector.normalize(Vector.sub(p.targetPos, {x: p.startX, y: p.startY}));
             const nextLx = p.x + rawDir.x * lookAheadDist;
             const nextLy = p.y + rawDir.y * lookAheadDist;
             const nextProgress = Math.min(1, Math.max(0, Vector.dist({x: p.startX, y: p.startY}, {x: nextLx, y: nextLy}) / totalDist));

             const nextVis = getVisualPos(nextLx, nextLy, nextProgress);

             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);
             const spin = p.skill.visual === 'BOMB' ? (progress * 15) : 0;

             const isChaos = isChaosStyle(p.skill.color);
             const isUlt = p.skill.tag === 'ULT';

             list.push({
                 y: p.y + 50 + offsetP, z: 20, 
                 draw: (ctx) => {
                    // --- 1. Draw Trail ---
                    if (p.trail.length > 1) {
                        ctx.save();

                        if (p.skill.visual === 'ARROW') {
                            ctx.beginPath();
                            const tail = p.trail[0];
                            const tailDist = Vector.dist({x: p.startX, y: p.startY}, tail);
                            const tailVis = getVisualPos(tail.x, tail.y, tailDist/totalDist);
                            ctx.moveTo(tailVis.x, tailVis.y);
                            ctx.lineTo(headVis.x, headVis.y);

                            ctx.strokeStyle = `rgba(255, 255, 255, 0.4)`;
                            ctx.lineWidth = 1;
                            ctx.stroke();
                        } else {
                            ctx.lineCap = 'round';
                            ctx.lineJoin = 'round';
                            ctx.globalCompositeOperation = 'lighter';

                            const trailPoints = p.trail.map(t => {
                                const d = Vector.dist({x: p.startX, y: p.startY}, t);
                                return getVisualPos(t.x, t.y, d/totalDist);
                            });
                            trailPoints.push(headVis);

                            for (let i = 0; i < trailPoints.length - 1; i++) {
                                const pt = trailPoints[i];
                                const next = trailPoints[i+1];
                                const ratio = i / (trailPoints.length - 1); 

                                const baseWidth = (p.skill.visual === 'FIREBALL' || p.skill.visual === 'SMASH') ? 24 : 12;
                                ctx.lineWidth = baseWidth * ratio * (isUlt ? 1.5 : 0.8);
                                ctx.strokeStyle = p.skill.color;

                                ctx.beginPath();
                                ctx.moveTo(pt.x, pt.y);
                                ctx.lineTo(next.x, next.y);

                                if (isChaos) {
                                    ctx.globalAlpha = ratio * 0.8; 
                                } else {
                                    ctx.globalAlpha = ratio * 0.5;
                                }
                                ctx.stroke();

                                if (!isChaos) {
                                    ctx.lineWidth = baseWidth * ratio * 0.3;
                                    ctx.strokeStyle = '#fff';
                                    ctx.stroke();
                                }
                            }
                        }
                        ctx.restore();
                    }

                    // --- 2. Draw Shadow ---
                    // Only draw shadow if we are decently above ground to avoid clutter
                    const altitude = headVis.shadowY - headVis.y;
                    if (altitude > 5) {
                        ctx.save();
                        ctx.translate(headVis.x, headVis.shadowY);
                        // Make shadow shrink as projectile goes higher
                        const shadowScale = Math.max(0.2, 1 - altitude/400);
                        ctx.scale(shadowScale, shadowScale);
                        ctx.fillStyle = 'rgba(0,0,0,0.3)';
                        ctx.beginPath(); ctx.ellipse(0, 0, 12, 6, 0, 0, Math.PI*2); ctx.fill();
                        ctx.restore();
                    }

                    // --- 3. Draw Projectile Head ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.y);
                    if (p.skill.visual === 'BOMB') ctx.rotate(spin);
                    else ctx.rotate(angle);

                    const img = AssetManager.getProjectile(p.skill.visual || 'BOLT', p.skill.color);
                    if (img && img.width > 0) {
                        // Projectile Size Scaling
                        // Default sprites are 96x64 which is huge for a 36px hex.
                        // Standard Attack: 0.6x
                        // Ult: 1.0x or 1.2x for Bombs
                        let scale = 0.6;
                        if (isUlt) scale = 1.0;
                        if (p.skill.visual === 'BOMB' || p.skill.visual === 'FIREBALL') scale *= 1.2;

                        ctx.scale(scale, scale);
                        ctx.drawImage(img, -48, -32, 96, 64);
                    }
                    ctx.restore();
                 }
             });
        });

        return list;
    }
};

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

// Helper: Cubic Ease In Out for Snappy Hit
function easeAttack(t: number): number {
    // Input t: 0.0 -> 1.0
    // We want the "Hit" to happen around 0.4-0.5
    // Windup: 0.0 -> 0.4 (Slow back)
    // Strike: 0.4 -> 0.5 (Fast forward)
    // Recover: 0.5 -> 1.0 (Slow return)

    if (t < 0.4) {
        // Windup (0 to 1)
        const p = t / 0.4;
        return -0.3 * (p * p); // Pull back slightly
    } else if (t < 0.5) {
        // Strike (0 to 1)
        const p = (t - 0.4) / 0.1;
        // Map -0.3 -> 1.0 very fast
        return -0.3 + (1.3 * p); 
    } else {
        // Recover (1 to 0)
        const p = (t - 0.5) / 0.5;
        // Ease out from 1.0 back to 0
        return 1.0 * (1 - p * p);
    }
}

export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#60a5fa'; 

        // 1. ANIMATION STATE CALCULATION
        // Body Float: Gentle vertical motion
        const floatY = (agent.hp > 0) ? Math.sin(t * 2) * 2 : 0;

        // Attack Animation Vars
        let armRot = 0;     // Weapon rotation
        let armX = 0;       // Weapon reach
        let armY = 0;
        let bodyRecoil = 0; // Body moving back slightly during hit

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const p = getCastProgress(agent);

            if (agent.role === Role.RANGER || agent.role === Role.MAGE) {
                // Ranged/Magic: Thrust forward / Recoil
                // Use custom ease for thrust
                const thrust = easeAttack(p);
                // Clamp negative windup for ranged visuals
                const forward = Math.max(0, thrust); 

                armX = forward * 15;
                if (p > 0.4 && p < 0.6) bodyRecoil = -3; // Kickback at fire moment
                if (p < 0.4) armRot = -0.2 * (p/0.4); // Aim adjust

            } else {
                // Melee: Swing Arc with SNAP
                const swing = easeAttack(p);

                // Swing Rotation: -60deg (Back) to +90deg (Forward)
                // easeAttack returns approx -0.3 to 1.0
                // Map that to angle
                armRot = (swing * Math.PI / 1.8); 

                // Extension during hit
                if (swing > 0.5) armX = 15 * swing; // Reach out
            }
        }

        ctx.save();

        // Apply Silhouette settings if needed
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.translate(bodyRecoil, floatY);
            // Simple box for occlusion
            ctx.strokeRect(-15, -60, 30, 60);
            ctx.restore();
            return;
        }

        // --- RIM LIGHT (OUTLINE) ---
        // Adds visibility on dark backgrounds
        if (agent.hp > 0) {
            ctx.shadowColor = 'rgba(255, 255, 255, 0.4)';
            ctx.shadowBlur = 10;
        }

        // --- RENDER START ---

        // Apply Global Position Offsets
        ctx.translate(bodyRecoil, floatY);

        // --- 1. BACK WEAPON / CAPE (Layer 0) ---
        // Imperial Cape
        drawCape(ctx, t, '#2563eb');

        // --- 2. OFF-HAND (Shield/Book) - Right Hand (Screen Left) ---
        // For Tank/Support, they hold something here.
        ctx.save();
        ctx.translate(-20, -35); // Left Shoulder position
        // Idle bob for offhand
        ctx.translate(0, Math.sin(t * 2.5 + 1) * 2); 

        if (agent.role === Role.TANK) {
            drawImperialShield(ctx);
        } else if (agent.role === Role.SUPPORT || agent.role === Role.MAGE) {
            drawImperialTome(ctx, t);
        }
        ctx.restore();

        // --- 3. BODY (Torso + Head) ---
        drawImperialBody(ctx, agent.role);

        // --- 4. MAIN HAND (Weapon) - Left Hand (Screen Right) ---
        ctx.save();
        ctx.translate(20, -35); // Right Shoulder pivot
        ctx.rotate(armRot);     // Apply Attack Rotation
        ctx.translate(armX, armY); // Apply Reach

        drawImperialWeapon(ctx, agent.role, t);

        ctx.restore();

        // Turn off glow for status effects
        ctx.shadowBlur = 0;

        ctx.restore();
    }
};

