import { GameEngine, Agent } from "../game";
import { Role, Team, Skill, AnimState } from "../../types";
import { UNIT_DB } from "../../data/units";
import { COLORS } from "../../constants";
import { HexUtils } from "../utils";

export class AgentManager {
    constructor() {}

    public addAgent(engine: GameEngine, team: Team, q: number, r: number, hpOverride?: number): Agent | null {
        if (!engine.map.isValid(q, r) || engine.map.isBlocked(q, r, engine)) return null;

        const a = new Agent(team, q, r, engine.mapConfig);

        // Smart Role Selection Strategy
        // Count existing roles in the team to maintain composition balance
        const allRoles = [Role.TANK, Role.WARRIOR, Role.RANGER, Role.MAGE, Role.SUPPORT];
        const teamAgents = engine.agents.filter(ag => ag.team === team);
        const roleCounts = new Map<Role, number>();
        allRoles.forEach(role => roleCounts.set(role, 0));
        teamAgents.forEach(ag => roleCounts.set(ag.role, (roleCounts.get(ag.role) || 0) + 1));

        // Find roles with minimum count
        let minCount = 999;
        roleCounts.forEach(c => { if(c < minCount) minCount = c; });

        const candidates = allRoles.filter(role => roleCounts.get(role) === minCount);
        a.role = candidates[Math.floor(Math.random() * candidates.length)];

        // ID Generation
        const suffix = Math.random().toString(36).substr(2, 4).toUpperCase();
        a.id = `${a.role}-${suffix}`;

        // Apply Base Stats from DB
        const stats = UNIT_DB[a.role];
        a.maxHp = hpOverride || stats.maxHp;
        a.hp = a.maxHp;
        a.maxMp = stats.maxMp;
        a.moveSpeed = stats.moveSpeed; 

        // Critical Fix: Copy Physics/Movement properties
        a.movementType = stats.movementType;
        a.jump = stats.jump;
        a.weight = stats.weight;

        // Skill Selection: 1 Ult, 1 Active, 1 Basic
        const validSkills = engine.skillDB.filter(s => s.role === a.role && (s.team === undefined || s.team === team));
        const rnd = (ar: Skill[]) => ar.length > 0 ? ar[Math.floor(Math.random() * ar.length)].id : null;

        a.skillIds = [
            rnd(validSkills.filter(s => s.tag === 'ULT')),
            rnd(validSkills.filter(s => s.tag === 'ACTIVE')),
            rnd(validSkills.filter(s => s.tag === 'BASIC'))
        ];

        // Spawn Effect
        a.spawnTimer = 0.5;
        engine.events.push({ 
            type: 'SPAWN', 
            pos: { x: a.px, y: a.py },
            color: COLORS[team],
            sourceId: a.id
        });

        // Register
        engine.agents.push(a);
        engine.agentMap.set(HexUtils.hash(q, r), a);

        return a;
    }

    public handleDeadState(a: Agent, engine: GameEngine) {
        if (a.fullyDead) return;

        if (!a.deadLogged) {
            engine.log(a, '死亡', null, '陣亡');

            // Push Event: Renderer will handle the visual explosion (Shatter)
            engine.events.push({ 
                type: 'DEATH', 
                pos: {x: a.px, y: a.py}, 
                sourceId: a.id,
                team: a.team // Pass team for color coding debris
            });

            a.deadLogged = true;
            a.setAnim(AnimState.DEAD);

            // Remove from spatial map so others can walk here
            engine.agentMap.delete(HexUtils.hash(a.q, a.r));

            // INSTANT VANISH: logic is done, body is hidden, particles take over
            a.fullyDead = true; 
            a.visualStatus = 'NONE';
            a.isMoving = false; 
            a.path = [];
        }
    }
}

import { GameEngine } from "../../../game";
import { Vector, HexUtils } from "../../../utils";
import { AssetManager } from "../../../assets";
import { RenderableItem } from "../../grid";
import { getTransitionOffset, isChaosStyle } from "../utils";

const UNIT_CHEST_HEIGHT = 40;

export const ProjectileRenderer = {
    collect(
        engine: GameEngine,
        getTerrainHeight: (q: number, r: number) => number,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ): RenderableItem[] {
        const list: RenderableItem[] = [];

        engine.projectiles.forEach(p => {
             const offsetP = getTransitionOffset(p.x, p.y, engine.mapConfig, transitionT, transitionPhase);
             if (offsetP > 500) return;

             let hStart = 0, hEnd = 0;
             let totalDist = Vector.dist({x: p.startX, y: p.startY}, p.targetPos);
             if (totalDist < 1) totalDist = 1;

             if (getTerrainHeight && engine.mapConfig) {
                 const startHex = HexUtils.fromPx(p.startX, p.startY, engine.mapConfig);
                 const targetHex = HexUtils.fromPx(p.targetPos.x, p.targetPos.y, engine.mapConfig);
                 hStart = getTerrainHeight(startHex.q, startHex.r);
                 hEnd = getTerrainHeight(targetHex.q, targetHex.r);
             }

             // Calculate Visual Position with Arcing/Wobble
             const getVisualPos = (lx: number, ly: number, flightProgress: number) => {
                 const t = flightProgress;
                 // Trajectory Height: Interpolated line between shooter and target
                 const trajectoryTerrainHeight = hStart + (hEnd - hStart) * t;

                 // Actual Ground Height: Look up what's directly underneath the projectile now
                 const currentHex = HexUtils.fromPx(lx, ly, engine.mapConfig);
                 const groundHeight = getTerrainHeight(currentHex.q, currentHex.r);

                 let arcOffset = 0;

                 // TYPE 1: PHYSICAL ARC (Arrow, Bomb) - Gravity based
                 if (p.skill.visual === 'ARROW' || p.skill.visual === 'BOMB') {
                     // Dynamic Arc Height: Scale based on distance to avoid ICBM effect on short shots
                     // Min arc 10, max arc 150 + bonus for Bombs
                     const distFactor = Math.min(150, totalDist * 0.25);
                     const baseArc = p.skill.visual === 'BOMB' ? 100 : 20;
                     const arcHeight = baseArc + distFactor;

                     // Parabola: 4 * h * t * (1-t)
                     arcOffset = 4 * arcHeight * t * (1 - t);
                 } 
                 // TYPE 2: MAGICAL (Bolt, Fireball) - Wobble/Straight
                 else if (p.skill.visual === 'BOLT' || p.skill.visual === 'FIREBALL') {
                     // Sine wave wobble based on distance traveled
                     const wobbleFreq = 0.2; 
                     const wobbleAmp = 10;
                     arcOffset = Math.sin(lx * wobbleFreq + ly * wobbleFreq) * wobbleAmp;
                 }

                 const off = getTransitionOffset(lx, ly, engine.mapConfig, transitionT, transitionPhase);

                 return {
                     x: lx,
                     // Projectile follows trajectory + arc
                     y: ly - trajectoryTerrainHeight - UNIT_CHEST_HEIGHT - arcOffset + off,
                     // Shadow sticks to the ACTUAL ground
                     shadowY: ly - groundHeight + off
                 };
             };

             const currentDist = Vector.dist({x: p.startX, y: p.startY}, {x: p.x, y: p.y});
             const progress = Math.min(1, Math.max(0, currentDist / totalDist));
             const headVis = getVisualPos(p.x, p.y, progress);

             // Look-Ahead Rotation Calculation
             const lookAheadDist = 10;
             const rawDir = Vector.normalize(Vector.sub(p.targetPos, {x: p.startX, y: p.startY}));
             const nextLx = p.x + rawDir.x * lookAheadDist;
             const nextLy = p.y + rawDir.y * lookAheadDist;
             const nextProgress = Math.min(1, Math.max(0, Vector.dist({x: p.startX, y: p.startY}, {x: nextLx, y: nextLy}) / totalDist));

             const nextVis = getVisualPos(nextLx, nextLy, nextProgress);

             const angle = Math.atan2(nextVis.y - headVis.y, nextVis.x - headVis.x);
             const spin = p.skill.visual === 'BOMB' ? (progress * 15) : 0;

             const isChaos = isChaosStyle(p.skill.color);
             const isUlt = p.skill.tag === 'ULT';

             list.push({
                 y: p.y + 50 + offsetP, z: 20, 
                 draw: (ctx) => {
                    // --- 1. Draw Trail ---
                    if (p.trail.length > 1) {
                        ctx.save();

                        if (p.skill.visual === 'ARROW') {
                            ctx.beginPath();
                            const tail = p.trail[0];
                            const tailDist = Vector.dist({x: p.startX, y: p.startY}, tail);
                            const tailVis = getVisualPos(tail.x, tail.y, tailDist/totalDist);
                            ctx.moveTo(tailVis.x, tailVis.y);
                            ctx.lineTo(headVis.x, headVis.y);

                            ctx.strokeStyle = `rgba(255, 255, 255, 0.4)`;
                            ctx.lineWidth = 1;
                            ctx.stroke();
                        } else {
                            ctx.lineCap = 'round';
                            ctx.lineJoin = 'round';
                            ctx.globalCompositeOperation = 'lighter';

                            const trailPoints = p.trail.map(t => {
                                const d = Vector.dist({x: p.startX, y: p.startY}, t);
                                return getVisualPos(t.x, t.y, d/totalDist);
                            });
                            trailPoints.push(headVis);

                            for (let i = 0; i < trailPoints.length - 1; i++) {
                                const pt = trailPoints[i];
                                const next = trailPoints[i+1];
                                const ratio = i / (trailPoints.length - 1); 

                                const baseWidth = (p.skill.visual === 'FIREBALL' || p.skill.visual === 'SMASH') ? 24 : 12;
                                ctx.lineWidth = baseWidth * ratio * (isUlt ? 1.5 : 0.8);
                                ctx.strokeStyle = p.skill.color;

                                ctx.beginPath();
                                ctx.moveTo(pt.x, pt.y);
                                ctx.lineTo(next.x, next.y);

                                if (isChaos) {
                                    ctx.globalAlpha = ratio * 0.8; 
                                } else {
                                    ctx.globalAlpha = ratio * 0.5;
                                }
                                ctx.stroke();

                                if (!isChaos) {
                                    ctx.lineWidth = baseWidth * ratio * 0.3;
                                    ctx.strokeStyle = '#fff';
                                    ctx.stroke();
                                }
                            }
                        }
                        ctx.restore();
                    }

                    // --- 2. Draw Shadow ---
                    // Only draw shadow if we are decently above ground to avoid clutter
                    const altitude = headVis.shadowY - headVis.y;
                    if (altitude > 5) {
                        ctx.save();
                        ctx.translate(headVis.x, headVis.shadowY);
                        // Make shadow shrink as projectile goes higher
                        const shadowScale = Math.max(0.2, 1 - altitude/400);
                        ctx.scale(shadowScale, shadowScale);
                        ctx.fillStyle = 'rgba(0,0,0,0.3)';
                        ctx.beginPath(); ctx.ellipse(0, 0, 12, 6, 0, 0, Math.PI*2); ctx.fill();
                        ctx.restore();
                    }

                    // --- 3. Draw Projectile Head ---
                    ctx.save();
                    ctx.translate(headVis.x, headVis.y);
                    if (p.skill.visual === 'BOMB') ctx.rotate(spin);
                    else ctx.rotate(angle);

                    const img = AssetManager.getProjectile(p.skill.visual || 'BOLT', p.skill.color);
                    if (img && img.width > 0) {
                        // Projectile Size Scaling
                        // Default sprites are 96x64 which is huge for a 36px hex.
                        // Standard Attack: 0.6x
                        // Ult: 1.0x or 1.2x for Bombs
                        let scale = 0.6;
                        if (isUlt) scale = 1.0;
                        if (p.skill.visual === 'BOMB' || p.skill.visual === 'FIREBALL') scale *= 1.2;

                        ctx.scale(scale, scale);
                        ctx.drawImage(img, -48, -32, 96, 64);
                    }
                    ctx.restore();
                 }
             });
        });

        return list;
    }
};

import { Agent } from "../../game";
import { AssetManager } from "../../assets";
import { SpriteManager } from "../../sprites";
import { Team } from "../../../types";

// =================================================================================
// 🧚 UNIT VISUAL EFFECTS (Flight, Casting, Status)
// =================================================================================

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const isBlue = agent.team === Team.BLUE;
    const color = isBlue ? '#60a5fa' : '#f87171';

    // We are at Ground Level (0,0) in the scaled context.
    // Unit Feet are at (physX, physY - physZ).

    const feetX = physX;
    const feetY = physY - physZ; 

    ctx.save();

    // 1. Ground Anchor (The Base)
    // Rotating Rune Ring - Clear indication of ground position
    ctx.save();
    ctx.scale(1, 0.58); // Isometric flat on ground
    ctx.rotate(t * 0.5);

    // Outer dashed ring
    ctx.globalAlpha = 0.6;
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.setLineDash([8, 4]);
    ctx.beginPath();
    ctx.arc(0, 0, 18, 0, Math.PI * 2);
    ctx.stroke();

    // Inner solid ring/plate
    ctx.setLineDash([]);
    ctx.lineWidth = 1;
    ctx.globalAlpha = 0.3;
    ctx.beginPath();
    ctx.arc(0, 0, 12, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();

    // 2. Holographic Tether (The Lift)
    // Only visible if unit is airborne to show connection
    if (physZ > 5) {
        const grad = ctx.createLinearGradient(0, 0, feetX, feetY);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent'); // Fade out near unit feet

        ctx.strokeStyle = grad;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.5;

        // Draw Main Tether Line
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(feetX, feetY);
        ctx.stroke();

        // Draw Moving Energy Pulses up the tether
        const pulseCount = 3;
        ctx.fillStyle = isBlue ? '#e0f2fe' : '#fecaca';
        ctx.globalAlpha = 0.8;

        for(let i=0; i<pulseCount; i++) {
            const p = (t * 0.8 + i / pulseCount) % 1.0; // 0 to 1, faster speed
            const px = feetX * p;
            const py = feetY * p;

            // Draw small horizontal dash/disk traveling up
            // Scale based on height to simulate perspective
            const scale = 1 - p * 0.5;
            ctx.beginPath();
            ctx.ellipse(px, py, 4 * scale, 2 * scale, 0, 0, Math.PI*2);
            ctx.fill();
        }
    }

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const color = agent.team === Team.BLUE ? '#bae6fd' : '#fecaca'; 

    ctx.save();
    ctx.translate(0, 5); // Just below body
    ctx.scale(1, 0.5); 

    // Rotating Wind/Energy Swirl at Feet
    ctx.rotate(t * 8); // Faster spin for thrusters

    // Inner Turbine Ring
    ctx.beginPath();
    ctx.arc(0, 0, 10, 0, Math.PI * 2);
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.6;
    ctx.stroke();

    // Outer Thruster Arcs
    ctx.beginPath();
    // 3 Arcs for stability look
    for(let i=0; i<3; i++) {
        const offset = i * (Math.PI * 2 / 3);
        const arcLen = Math.PI / 2;
        ctx.moveTo(Math.cos(offset) * 18, Math.sin(offset) * 18);
        ctx.arc(0, 0, 18, offset, offset + arcLen);
    }

    ctx.strokeStyle = color;
    ctx.lineWidth = 3;
    ctx.globalAlpha = 0.5 + Math.sin(t * 20) * 0.2; // Flicker
    ctx.stroke();

    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    // 1. Rising Energy Lines
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = color;
    ctx.lineWidth = 3; 
    const lineCount = 5 + Math.floor(progress * 8); 
    for(let i=0; i<lineCount; i++) {
        const h = (t * 150 + i * 40) % 90; 
        const alpha = 1 - (h / 90);
        const xOff = Math.sin(t * 15 + i) * 20 * (1-progress); 
        ctx.globalAlpha = alpha;
        ctx.beginPath(); ctx.moveTo(xOff, 15 - h); ctx.lineTo(xOff, 15 - h - 20); ctx.stroke();
    }

    // 2. Converging Rings
    if (progress > 0.2) {
        const ringScale = (1 - progress) * 2.5; 
        ctx.globalAlpha = progress;
        ctx.lineWidth = 2;
        ctx.beginPath(); ctx.ellipse(0, -20, 30 * ringScale, 10 * ringScale, 0, 0, Math.PI*2); ctx.stroke();

        ctx.save(); ctx.translate(0, -20); ctx.rotate(t * 10);
        ctx.beginPath(); ctx.ellipse(0, 0, 20 * ringScale, 5 * ringScale, 0, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. Hand Glow
    ctx.globalAlpha = 0.4 + (Math.sin(t * 20) * 0.2) + (progress * 0.6);
    ctx.fillStyle = color;
    ctx.beginPath(); ctx.arc(0, -20, 10 + progress * 15, 0, Math.PI*2); ctx.fill();

    // 4. Final Flash
    if (progress > 0.9) {
        ctx.globalAlpha = (progress - 0.9) * 10;
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(0, -20, 30, 0, Math.PI*2); ctx.fill();
    }

    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, -110);

            const glow = AssetManager.getGlowSprite(skill.color);
            ctx.globalCompositeOperation = 'lighter';
            const pulse = 0.5 + Math.sin(t * 10) * 0.1;
            ctx.globalAlpha = 0.3 * pulse;
            ctx.drawImage(glow, -40, -40, 80, 80);

            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    const HEAD_Y = -60; 

    // 1. FROZEN - ICE PRISM (Encasing the unit)
    if (agent.visualStatus === 'FROZEN') {
        ctx.save();
        ctx.translate(0, -40); // Center of body

        // Draw Hexagonal Prism
        const w = 30;
        const h = 50;

        ctx.globalCompositeOperation = 'source-over';
        // Back Faces
        ctx.fillStyle = 'rgba(186, 230, 253, 0.4)'; // Light Blue
        ctx.beginPath();
        ctx.moveTo(-w, -h); ctx.lineTo(w, -h); ctx.lineTo(w, h); ctx.lineTo(-w, h);
        ctx.fill();

        // Front Faces (Glassy)
        const grad = ctx.createLinearGradient(-w, -h, w, h);
        grad.addColorStop(0, 'rgba(255,255,255,0.6)');
        grad.addColorStop(0.5, 'rgba(56, 189, 248, 0.3)');
        grad.addColorStop(1, 'rgba(14, 165, 233, 0.5)');

        ctx.fillStyle = grad;
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 2;

        ctx.beginPath();
        ctx.moveTo(0, -h - 10); // Top Tip
        ctx.lineTo(w + 5, -h + 10);
        ctx.lineTo(w, h);
        ctx.lineTo(0, h + 10); // Bottom Tip
        ctx.lineTo(-w, h);
        ctx.lineTo(-w - 5, -h + 10);
        ctx.closePath();
        ctx.fill();
        ctx.stroke();

        // Glint
        ctx.globalCompositeOperation = 'lighter';
        ctx.beginPath();
        ctx.moveTo(0, -h-10); ctx.lineTo(0, h+10);
        ctx.strokeStyle = 'rgba(255,255,255,0.5)';
        ctx.stroke();

        ctx.restore();
    }

    // 2. BANISH - GHOSTLY CAGE (Rotates around unit)
    if (agent.banished && agent.visualStatus !== 'POLYMORPH') {
        ctx.translate(0, -30); // Body center

        ctx.globalCompositeOperation = 'source-over';
        ctx.strokeStyle = '#c084fc';
        ctx.lineWidth = 3;
        ctx.globalAlpha = 0.8;

        // Vertical Bars orbiting (Simulated 3D Cylinder)
        const bars = 5;
        const radius = 25;
        const height = 50;

        for(let i=0; i<bars; i++) {
            // Rotate bars over time
            const angle = t * 2 + (i / bars) * Math.PI * 2;
            const x = Math.cos(angle) * radius;
            const z = Math.sin(angle); // Depth

            // Perspective scale
            const scale = 1 + z * 0.1;
            const alpha = 0.5 + (z + 1) * 0.25; // Fade back bars

            ctx.globalAlpha = alpha;
            ctx.beginPath();
            ctx.moveTo(x, -height);
            ctx.lineTo(x, height);
            ctx.stroke();

            // Runes on bars
            if (i % 2 === 0) {
                ctx.fillStyle = '#d8b4fe';
                ctx.beginPath(); ctx.arc(x, -height/2 + Math.sin(t*3+i)*10, 3, 0, Math.PI*2); ctx.fill();
            }
        }

        // Top and Bottom Rings
        ctx.globalAlpha = 0.6;
        ctx.save();
        ctx.scale(1, 0.3); // Isometric
        ctx.beginPath(); ctx.arc(0, -height / 0.3, radius, 0, Math.PI*2); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, height / 0.3, radius, 0, Math.PI*2); ctx.stroke();
        ctx.restore();
    }

    // 3. STUN - 3D DIZZY RING
    if (agent.stunTimer > 0 && !agent.banished && agent.visualStatus !== 'FROZEN') {
        ctx.translate(0, HEAD_Y - 10);

        ctx.globalCompositeOperation = 'lighter';
        ctx.lineWidth = 3;

        const count = 5;
        const radius = 25;

        // Orbiting Stars
        for(let i=0; i<count; i++) {
            const angle = t * 4 + (i / count) * Math.PI * 2;
            // 3D Orbit: Y is squashed
            const x = Math.cos(angle) * radius;
            const y = Math.sin(angle) * radius * 0.3;
            // Z-sort simulation: if sin(angle) > 0, it's in front
            const scale = 1 + Math.sin(angle) * 0.3;

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(scale, scale);

            ctx.fillStyle = '#facc15';
            ctx.shadowColor = '#fbbf24';
            ctx.shadowBlur = 10;

            // Draw Star
            ctx.beginPath();
            const starPts = 5;
            for(let j=0; j<starPts*2; j++) {
                const r = j%2===0 ? 6 : 2;
                const a = j * Math.PI / starPts;
                ctx.lineTo(Math.cos(a)*r, Math.sin(a)*r);
            }
            ctx.fill();
            ctx.restore();
        }
    }

    // 4. SILENCE - FLOATING RUNE SEAL
    if (agent.silenceTimer > 0) {
        ctx.translate(0, HEAD_Y - 15);

        const scale = 1 + Math.sin(t * 5) * 0.1;
        ctx.scale(scale, scale);

        ctx.fillStyle = '#1e1b4b'; 
        ctx.strokeStyle = '#a855f7';
        ctx.lineWidth = 2;
        ctx.shadowColor = '#c084fc';
        ctx.shadowBlur = 10;

        // Rune Box
        ctx.beginPath();
        ctx.rect(-15, -10, 30, 20);
        ctx.fill();
        ctx.stroke();

        // "X" or Rune Text
        ctx.beginPath();
        ctx.moveTo(-8, -5); ctx.lineTo(8, 5);
        ctx.moveTo(8, -5); ctx.lineTo(-8, 5);
        ctx.stroke();
    }

    // 5. DoT - Rising Bubbles / Smoke
    if (agent.dotTimer > 0) {
        ctx.translate(0, -40);
        const count = 3;
        for(let i=0; i<count; i++) {
            const phase = (t + i/count) % 1;
            const y = -phase * 40;
            const x = Math.sin(phase * 10 + i) * 10;
            const size = (1-phase) * 6;

            ctx.fillStyle = i%2===0 ? '#10b981' : '#a855f7'; 
            ctx.globalAlpha = (1-phase);
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
    }

    // 6. HoT - Spiraling +
    if (agent.hotTimer > 0) {
        ctx.translate(0, -30);
        const angle = -t * 3;
        const radius = 25;

        const x = Math.cos(angle) * radius;
        const y = Math.sin(angle) * radius * 0.3; // Flattened

        ctx.fillStyle = '#4ade80';
        ctx.font = 'bold 16px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('+', x, y);
    }

    ctx.restore();
}

export function drawSpawnIndicator(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, scale: number) {
    const assets = SpriteManager.getUnitImages(agent.role, agent.team);
    const totalDuration = 0.5;
    const alpha = Math.max(0, agent.spawnTimer / totalDuration);
    const yOffset = -85 * scale; 

    ctx.save();
    ctx.translate(x, y + yOffset);
    const popScale = 1.0 + alpha * 0.2;
    ctx.scale(popScale, popScale);
    ctx.globalAlpha = alpha;

    ctx.fillStyle = 'rgba(15, 23, 42, 0.4)'; 
    ctx.strokeStyle = agent.team === Team.BLUE ? 'rgba(59, 130, 246, 0.8)' : 'rgba(239, 68, 68, 0.8)';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(0, 0, 18, 0, Math.PI*2); ctx.fill(); ctx.stroke();

    ctx.drawImage(assets.icon, -12, -12, 24, 24);

    ctx.font = 'bold 10px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = '#fff';
    ctx.strokeStyle = 'rgba(0,0,0,0.8)';
    ctx.lineWidth = 2;
    ctx.strokeText(agent.role, 0, 28);
    ctx.fillText(agent.role, 0, 28);

    ctx.restore();
}

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

// Helper: Cubic Ease In Out for Snappy Hit
function easeAttack(t: number): number {
    // Input t: 0.0 -> 1.0
    // We want the "Hit" to happen around 0.4-0.5
    // Windup: 0.0 -> 0.4 (Slow back)
    // Strike: 0.4 -> 0.5 (Fast forward)
    // Recover: 0.5 -> 1.0 (Slow return)

    if (t < 0.4) {
        // Windup (0 to 1)
        const p = t / 0.4;
        return -0.3 * (p * p); // Pull back slightly
    } else if (t < 0.5) {
        // Strike (0 to 1)
        const p = (t - 0.4) / 0.1;
        // Map -0.3 -> 1.0 very fast
        return -0.3 + (1.3 * p); 
    } else {
        // Recover (1 to 0)
        const p = (t - 0.5) / 0.5;
        // Ease out from 1.0 back to 0
        return 1.0 * (1 - p * p);
    }
}

export const ImperialRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#60a5fa'; 

        // 1. ANIMATION STATE CALCULATION
        // Body Float: Gentle vertical motion
        const floatY = (agent.hp > 0) ? Math.sin(t * 2) * 2 : 0;

        // Attack Animation Vars
        let armRot = 0;     // Weapon rotation
        let armX = 0;       // Weapon reach
        let armY = 0;
        let bodyRecoil = 0; // Body moving back slightly during hit

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const p = getCastProgress(agent);

            if (agent.role === Role.RANGER || agent.role === Role.MAGE) {
                // Ranged/Magic: Thrust forward / Recoil
                // Use custom ease for thrust
                const thrust = easeAttack(p);
                // Clamp negative windup for ranged visuals
                const forward = Math.max(0, thrust); 

                armX = forward * 15;
                if (p > 0.4 && p < 0.6) bodyRecoil = -3; // Kickback at fire moment
                if (p < 0.4) armRot = -0.2 * (p/0.4); // Aim adjust

            } else {
                // Melee: Swing Arc with SNAP
                const swing = easeAttack(p);

                // Swing Rotation: -60deg (Back) to +90deg (Forward)
                // easeAttack returns approx -0.3 to 1.0
                // Map that to angle
                armRot = (swing * Math.PI / 1.8); 

                // Extension during hit
                if (swing > 0.5) armX = 15 * swing; // Reach out
            }
        }

        ctx.save();

        // Apply Silhouette settings if needed
        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.translate(bodyRecoil, floatY);
            // Simple box for occlusion
            ctx.strokeRect(-15, -60, 30, 60);
            ctx.restore();
            return;
        }

        // --- RIM LIGHT (OUTLINE) ---
        // Adds visibility on dark backgrounds
        if (agent.hp > 0) {
            ctx.shadowColor = 'rgba(255, 255, 255, 0.4)';
            ctx.shadowBlur = 10;
        }

        // --- RENDER START ---

        // Apply Global Position Offsets
        ctx.translate(bodyRecoil, floatY);

        // --- 1. BACK WEAPON / CAPE (Layer 0) ---
        // Imperial Cape
        drawCape(ctx, t, '#2563eb');

        // --- 2. OFF-HAND (Shield/Book) - Right Hand (Screen Left) ---
        // For Tank/Support, they hold something here.
        ctx.save();
        ctx.translate(-20, -35); // Left Shoulder position
        // Idle bob for offhand
        ctx.translate(0, Math.sin(t * 2.5 + 1) * 2); 

        if (agent.role === Role.TANK) {
            drawImperialShield(ctx);
        } else if (agent.role === Role.SUPPORT || agent.role === Role.MAGE) {
            drawImperialTome(ctx, t);
        }
        ctx.restore();

        // --- 3. BODY (Torso + Head) ---
        drawImperialBody(ctx, agent.role);

        // --- 4. MAIN HAND (Weapon) - Left Hand (Screen Right) ---
        ctx.save();
        ctx.translate(20, -35); // Right Shoulder pivot
        ctx.rotate(armRot);     // Apply Attack Rotation
        ctx.translate(armX, armY); // Apply Reach

        drawImperialWeapon(ctx, agent.role, t);

        ctx.restore();

        // Turn off glow for status effects
        ctx.shadowBlur = 0;

        ctx.restore();
    }
};

// --- SUB-COMPONENT RENDERERS ---

function drawImperialBody(ctx: CanvasRenderingContext2D, role: Role) {
    const primary = '#2563eb'; // Blue
    const secondary = '#facc15'; // Gold
    const armorLight = '#f8fafc'; // White ceramic
    const armorDark = '#1e3a8a';  // Dark Blue

    // Torso Gradient
    const grad = ctx.createLinearGradient(-15, -50, 15, 0);
    grad.addColorStop(0, armorLight);
    grad.addColorStop(0.5, armorDark);
    grad.addColorStop(1, primary);

    ctx.fillStyle = grad;
    ctx.strokeStyle = secondary;
    ctx.lineWidth = 1.5;

    // Armor Shape
    ctx.beginPath();
    if (role === Role.TANK) {
        // Heavy Plate
        ctx.moveTo(-22, -45); ctx.lineTo(22, -45); // Wide Shoulders
        ctx.lineTo(15, 0); ctx.lineTo(-15, 0);     // Waist
        ctx.lineTo(-22, -45);
    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        // Robe Form
        ctx.moveTo(-12, -45); ctx.lineTo(12, -45);
        ctx.lineTo(18, 10); ctx.lineTo(-18, 10);
        ctx.lineTo(-12, -45);
    } else {
        // Standard Plate
        ctx.moveTo(-18, -45); ctx.lineTo(18, -45);
        ctx.lineTo(12, 5); ctx.lineTo(-12, 5);
        ctx.lineTo(-18, -45);
    }
    ctx.fill();
    ctx.stroke();

    // Core Crystal (Soul)
    ctx.fillStyle = '#fff';
    // Inner glow
    ctx.beginPath(); ctx.moveTo(0, -35); ctx.lineTo(6, -25); ctx.lineTo(0, -15); ctx.lineTo(-6, -25); ctx.fill();

    // Head
    ctx.save();
    ctx.translate(0, -50);

    // Halo
    if (role === Role.MAGE || role === Role.SUPPORT) {
        ctx.strokeStyle = secondary;
        ctx.beginPath(); ctx.arc(0, -5, 16, 0, Math.PI*2); ctx.stroke();
    }

    ctx.fillStyle = armorLight;
    ctx.strokeStyle = secondary;
    ctx.lineWidth = 1;
    ctx.beginPath();
    if (role === Role.TANK) ctx.rect(-10, -12, 20, 18); // Square Helm
    else ctx.ellipse(0, -2, 9, 11, 0, 0, Math.PI*2);    // Round Helm
    ctx.fill(); ctx.stroke();

    // Visor
    ctx.fillStyle = primary;
    ctx.fillRect(-8, -4, 16, 3);

    ctx.restore();
}

function drawCape(ctx: CanvasRenderingContext2D, t: number, color: string) {
    ctx.save();
    ctx.translate(0, -45);
    const wave = Math.sin(t * 3) * 5;
    ctx.fillStyle = 'rgba(30, 58, 138, 0.8)'; // Dark Blue liner
    ctx.beginPath();
    ctx.moveTo(-10, 0);
    ctx.lineTo(-15 + wave, 50);
    ctx.lineTo(15 + wave, 50);
    ctx.lineTo(10, 0);
    ctx.fill();
    ctx.restore();
}

function drawImperialHand(ctx: CanvasRenderingContext2D) {
    // "Servo-Hand": A floating sphere that magnetically holds weapons
    ctx.fillStyle = '#1e293b'; // Dark joint
    ctx.beginPath(); ctx.arc(0, 0, 6, 0, Math.PI*2); ctx.fill();
    ctx.fillStyle = '#facc15'; // Gold plate
    ctx.beginPath(); ctx.arc(0, 0, 4, 0, Math.PI*2); ctx.fill();
}

function drawImperialShield(ctx: CanvasRenderingContext2D) {
    drawImperialHand(ctx);

    // Tower Shield
    ctx.translate(-5, 10); // Offset from hand
    ctx.rotate(-Math.PI/12); // Tilt

    // Shield Body
    const grad = ctx.createLinearGradient(0, -30, 0, 30);
    grad.addColorStop(0, '#f8fafc');
    grad.addColorStop(1, '#2563eb');

    ctx.fillStyle = grad;
    ctx.strokeStyle = '#facc15';
    ctx.lineWidth = 3;

    ctx.beginPath();
    ctx.moveTo(-15, -30); ctx.lineTo(15, -30); // Top
    ctx.lineTo(15, 10);   // Right vertical
    ctx.lineTo(0, 40);    // Bottom tip
    ctx.lineTo(-15, 10);  // Left vertical
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // Energy Cross
    ctx.fillStyle = '#60a5fa';
    ctx.fillRect(-5, -20, 10, 40);
    ctx.fillRect(-12, -5, 24, 10);
}

function drawImperialTome(ctx: CanvasRenderingContext2D, t: number) {
    drawImperialHand(ctx);
    ctx.translate(0, -10);
    // Floating Book
    ctx.fillStyle = '#fff';
    ctx.fillRect(-10, -12, 20, 24); // Pages
    ctx.fillStyle = '#2563eb';
    ctx.fillRect(-12, -12, 4, 24); // Spine

    // Magic particles
    if (Math.sin(t*5) > 0) {
        ctx.fillStyle = '#facc15';
        ctx.fillRect(5, -20, 2, 2);
        ctx.fillRect(8, -25, 2, 2);
    }
}

function drawImperialWeapon(ctx: CanvasRenderingContext2D, role: Role, t: number) {
    drawImperialHand(ctx); // The Servo Hand

    if (role === Role.WARRIOR) {
        // ENERGY CLAYMORE
        ctx.rotate(Math.PI / 2); // Point forward

        // Hilt
        ctx.fillStyle = '#475569';
        ctx.fillRect(-4, -10, 8, 20); // Grip
        ctx.fillStyle = '#facc15';
        ctx.fillRect(-12, -10, 24, 4); // Crossguard

        // Blade (Energy)
        ctx.fillStyle = 'rgba(147, 197, 253, 0.8)'; // Light blue glass
        ctx.strokeStyle = '#2563eb';
        ctx.lineWidth = 2;

        ctx.beginPath();
        ctx.moveTo(-6, -10); 
        ctx.lineTo(-4, -70); // Tip Left
        ctx.lineTo(0, -80);  // Point
        ctx.lineTo(4, -70);  // Tip Right
        ctx.lineTo(6, -10);  // Base
        ctx.fill(); ctx.stroke();

    } else if (role === Role.TANK) {
        // POWER MACE
        ctx.rotate(Math.PI / 3); // Held angled

        // Handle
        ctx.fillStyle = '#475569';
        ctx.fillRect(-3, -10, 6, 50);

        // Head
        ctx.translate(0, -50);
        ctx.fillStyle = '#f8fafc';
        ctx.strokeStyle = '#facc15';
        ctx.lineWidth = 2;

        // Central Block
        ctx.fillRect(-12, -15, 24, 30);
        ctx.strokeRect(-12, -15, 24, 30);

        // Flanges
        ctx.fillStyle = '#2563eb';
        ctx.beginPath(); ctx.moveTo(0, -15); ctx.lineTo(-20, 0); ctx.lineTo(0, 15); ctx.fill();
        ctx.beginPath(); ctx.moveTo(0, -15); ctx.lineTo(20, 0); ctx.lineTo(0, 15); ctx.fill();

    } else if (role === Role.RANGER) {
        // COMPOSITE BOW
        // Held vertically
        ctx.translate(10, 0);

        ctx.strokeStyle = '#f8fafc';
        ctx.lineWidth = 3;

        // Bow Arc
        ctx.beginPath();
        ctx.arc(0, 0, 30, -Math.PI/2 - 0.5, Math.PI/2 + 0.5);
        ctx.stroke();

        // Energy String
        ctx.strokeStyle = '#60a5fa';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(0, -30); ctx.lineTo(0, 30);
        ctx.stroke();

    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        // STAFF
        ctx.rotate(-Math.PI / 6); // Angled back

        // Shaft
        ctx.fillStyle = '#b45309'; // Wood/Gold
        ctx.fillRect(-3, -40, 6, 80);

        // Head
        ctx.translate(0, -45);

        // Floating Crystal
        const float = Math.sin(t * 4) * 3;
        ctx.translate(0, float);

        ctx.fillStyle = role === Role.MAGE ? '#3b82f6' : '#facc15';

        ctx.beginPath();
        ctx.moveTo(0, -10); ctx.lineTo(8, 0); ctx.lineTo(0, 10); ctx.lineTo(-8, 0);
        ctx.fill();

        // Orbitals
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1;
        ctx.beginPath(); ctx.arc(0, 0, 14, 0, Math.PI*2); ctx.stroke();
    }
}

import { Agent } from "../../../game";
import { AnimState, Role } from "../../../../types";
import { getCastProgress } from "../utils";

// Helper: Cubic Ease In Out for Snappy Hit (Shared logic, copied for independence)
function easeAttack(t: number): number {
    if (t < 0.4) {
        // Windup (0 to 1) - Backswing
        const p = t / 0.4;
        return -0.4 * (p * p); 
    } else if (t < 0.5) {
        // Strike (0 to 1) - Fast Forward
        const p = (t - 0.4) / 0.1;
        return -0.4 + (1.4 * p); 
    } else {
        // Recover (1 to 0)
        const p = (t - 0.5) / 0.5;
        return 1.0 * (1 - p * p);
    }
}

export const CovenantRenderer = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean) {
        const silhouetteColor = '#ef4444'; 

        // 1. ANIMATION STATE
        // Jittery Hover (Unstable)
        const floatY = (agent.hp > 0) ? Math.sin(t * 5) * 1.5 + (Math.random()-0.5) : 0;

        // Attack Vars
        let armRot = 0;
        let armX = 0;
        let armY = 0;
        let bodyRecoil = 0;

        if (agent.animState === AnimState.ATTACK && agent.hp > 0) {
            const p = getCastProgress(agent);

            if (agent.role === Role.RANGER || agent.role === Role.MAGE) {
                // Ranged: Violent jerk
                const jerk = easeAttack(p);
                const forward = Math.max(0, jerk);

                armX = forward * 20;

                if (p > 0.4 && p < 0.5) {
                    armY = -5; // Kick up
                    bodyRecoil = -5; // Body kickback
                } 
            } else {
                // Melee: Heavy Chop (Brutal snap)
                const swing = easeAttack(p);

                // Big rotation: -100deg to +90deg
                armRot = swing * (Math.PI / 1.5);

                if (swing > 0.5) {
                    armX = 20 * swing;
                    armY = 10 * swing; // Downward slam visual
                }
            }
        }

        ctx.save();

        if (isSilhouette) {
            ctx.strokeStyle = silhouetteColor;
            ctx.lineWidth = 2;
            ctx.translate(bodyRecoil, floatY);
            // Spiky box
            ctx.beginPath();
            ctx.moveTo(-15, -60); ctx.lineTo(0, -70); ctx.lineTo(15, -60);
            ctx.lineTo(10, 0); ctx.lineTo(-10, 0); ctx.closePath();
            ctx.stroke();
            ctx.restore();
            return;
        }

        // --- RIM LIGHT (OUTLINE) ---
        // Adds visibility on dark backgrounds
        if (agent.hp > 0) {
            ctx.shadowColor = 'rgba(239, 68, 68, 0.4)'; // Reddish glow for Covenant
            ctx.shadowBlur = 10;
        }

        // --- RENDER START ---
        ctx.translate(bodyRecoil, floatY);

        // --- 1. BACK SPIKES (Layer 0) ---
        drawSpikes(ctx, t);

        // --- 2. OFF-HAND (Shield/Totem) - Screen Left ---
        ctx.save();
        ctx.translate(-22, -30);
        // Heavy breathing motion
        ctx.translate(0, Math.sin(t * 3) * 1);

        if (agent.role === Role.TANK) {
            drawCovenantShield(ctx);
        } else if (agent.role === Role.SUPPORT || agent.role === Role.MAGE) {
            drawCovenantTotem(ctx, t);
        }
        ctx.restore();

        // --- 3. BODY ---
        drawCovenantBody(ctx, agent.role);

        // --- 4. MAIN HAND (Weapon) - Screen Right ---
        ctx.save();
        ctx.translate(22, -30); // Shoulder
        ctx.rotate(armRot);
        ctx.translate(armX, armY);

        drawCovenantWeapon(ctx, agent.role, t);

        ctx.restore();

        // Turn off glow
        ctx.shadowBlur = 0;

        ctx.restore();
    }
};

// --- SUB-RENDERERS ---

function drawCovenantBody(ctx: CanvasRenderingContext2D, role: Role) {
    const primary = '#b91c1c'; // Blood Red
    const darkMetal = '#18181b'; // Obsidian
    const glow = '#ef4444'; // Bright Red

    // Body Gradient
    const grad = ctx.createLinearGradient(-15, -50, 15, 10);
    grad.addColorStop(0, primary);
    grad.addColorStop(0.6, darkMetal);
    grad.addColorStop(1, '#000');

    ctx.fillStyle = grad;
    ctx.strokeStyle = '#7f1d1d'; // Rust
    ctx.lineWidth = 1;

    // Shape: Angular/Coffin
    ctx.beginPath();
    if (role === Role.TANK) {
        // Bulk
        ctx.moveTo(-25, -40); ctx.lineTo(25, -40); // Broad shoulders
        ctx.lineTo(15, 10); ctx.lineTo(-15, 10);
        ctx.lineTo(-25, -40);
    } else {
        // Sharp
        ctx.moveTo(-18, -45); ctx.lineTo(18, -45);
        ctx.lineTo(8, 15); ctx.lineTo(-8, 15);
        ctx.lineTo(-18, -45);
    }
    ctx.fill();
    ctx.stroke();

    // Magma Fissure (Center Chest)
    ctx.strokeStyle = glow;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, -35);
    ctx.lineTo((Math.random()-0.5)*5, -25);
    ctx.lineTo(0, -15);
    ctx.stroke();

    // Head
    ctx.save();
    ctx.translate(0, -48);

    ctx.fillStyle = darkMetal;
    ctx.beginPath();
    // Horned Helm
    ctx.moveTo(-10, 5); ctx.lineTo(-12, -15); ctx.lineTo(-5, -5); 
    ctx.lineTo(5, -5); ctx.lineTo(12, -15); ctx.lineTo(10, 5);
    ctx.fill();

    // Cyclops Eye
    ctx.fillStyle = '#fca5a5';
    ctx.beginPath(); ctx.arc(0, 0, 3, 0, Math.PI*2); ctx.fill();

    ctx.restore();
}

function drawSpikes(ctx: CanvasRenderingContext2D, t: number) {
    ctx.save();
    ctx.translate(0, -40);
    ctx.fillStyle = '#27272a';
    ctx.beginPath();
    // Asymmetric spikes
    ctx.moveTo(-10, 0); ctx.lineTo(-25, -30 + Math.sin(t*5)*2); ctx.lineTo(-15, 0);
    ctx.moveTo(10, 0); ctx.lineTo(20, -25 + Math.cos(t*4)*2); ctx.lineTo(15, 0);
    ctx.fill();
    ctx.restore();
}

function drawCovenantHand(ctx: CanvasRenderingContext2D) {
    // "Fused Gauntlet": Angular block attached to arm
    ctx.fillStyle = '#450a0a'; // Dark Red Iron
    ctx.beginPath(); 
    ctx.moveTo(-6, -6); ctx.lineTo(6, -6); ctx.lineTo(4, 8); ctx.lineTo(-4, 8);
    ctx.fill();
}

function drawCovenantShield(ctx: CanvasRenderingContext2D) {
    drawCovenantHand(ctx);
    ctx.translate(-5, 10);

    // Scrap Wall Shield
    ctx.fillStyle = '#27272a'; // Iron
    ctx.strokeStyle = '#ef4444';
    ctx.lineWidth = 2;

    ctx.beginPath();
    // Jagged Octagon
    ctx.moveTo(-15, -25); ctx.lineTo(15, -20);
    ctx.lineTo(20, 0); ctx.lineTo(10, 25);
    ctx.lineTo(-15, 20); ctx.lineTo(-20, 0);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // Spikes on shield
    ctx.fillStyle = '#7f1d1d';
    ctx.beginPath();
    ctx.moveTo(0, 0); ctx.lineTo(0, -35); ctx.lineTo(5, -10); ctx.fill();
}

function drawCovenantTotem(ctx: CanvasRenderingContext2D, t: number) {
    drawCovenantHand(ctx);
    ctx.translate(0, 10); // Hold low

    // Totem Pole
    ctx.fillStyle = '#3f3f46';
    ctx.fillRect(-4, -40, 8, 50);

    // Skull/Orb top
    ctx.translate(0, -45);
    ctx.fillStyle = '#ef4444';
    ctx.beginPath();
    ctx.moveTo(-8, 0); ctx.lineTo(0, -10); ctx.lineTo(8, 0); ctx.lineTo(0, 10);
    ctx.fill();
}

function drawCovenantWeapon(ctx: CanvasRenderingContext2D, role: Role, t: number) {
    drawCovenantHand(ctx);

    if (role === Role.WARRIOR) {
        // BATTLE AXE
        ctx.rotate(Math.PI / 4); // Forward

        // Haft
        ctx.fillStyle = '#27272a';
        ctx.fillRect(-3, -10, 6, 60); // Long handle

        // Blade Head
        ctx.translate(0, -60); // Top of handle
        ctx.fillStyle = '#52525b'; // Steel
        ctx.strokeStyle = '#ef4444'; // Red edge
        ctx.lineWidth = 1;

        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(-25, -10); // Top tip
        ctx.quadraticCurveTo(-15, 10, -25, 30); // Blade edge curve
        ctx.lineTo(0, 20);
        ctx.fill(); ctx.stroke();

        // Spike on back
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(10, 5); ctx.lineTo(0, 10); ctx.fill();

    } else if (role === Role.TANK) {
        // MEAT CLEAVER
        ctx.rotate(Math.PI / 3);

        ctx.fillStyle = '#27272a';
        ctx.fillRect(-4, -5, 8, 20); // Handle

        ctx.fillStyle = '#7f1d1d'; // Rusted Metal
        ctx.beginPath();
        ctx.moveTo(-10, -10);
        ctx.lineTo(-10, -60); // Back spine
        ctx.lineTo(20, -60);  // Top flat
        ctx.lineTo(20, -10);  // Blade edge vertical
        ctx.lineTo(0, 0);
        ctx.fill();

        // Blood edge
        ctx.strokeStyle = '#ef4444'; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(20, -60); ctx.lineTo(20, -10); ctx.stroke();

    } else if (role === Role.RANGER) {
        // HEAVY CROSSBOW
        ctx.rotate(-Math.PI / 2); // Pointing forward

        ctx.fillStyle = '#18181b';
        ctx.fillRect(-5, -30, 10, 40); // Stock

        // Bow Arms
        ctx.strokeStyle = '#7f1d1d';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(-25, -25); ctx.lineTo(0, -30); ctx.lineTo(25, -25);
        ctx.stroke();

        // String
        ctx.strokeStyle = '#52525b'; ctx.lineWidth = 1;
        ctx.beginPath(); ctx.moveTo(-25, -25); ctx.lineTo(0, 0); ctx.lineTo(25, -25); ctx.stroke();

    } else if (role === Role.MAGE || role === Role.SUPPORT) {
        // RITUAL DAGGER / WAND
        ctx.rotate(Math.PI / 6);

        ctx.fillStyle = '#450a0a';
        ctx.beginPath();
        ctx.moveTo(0, 10);
        ctx.lineTo(-5, -30); // Wavy blade
        ctx.lineTo(0, -50);  // Point
        ctx.lineTo(5, -30);
        ctx.fill();

        // Glow Tip
        ctx.fillStyle = '#ef4444';
        ctx.beginPath(); ctx.arc(0, -50, 3, 0, Math.PI*2); ctx.fill();
    }
}
